content[9]=[[["When Ben was ten, his family visited a small island.", "Quando Ben tinha dez anos, a família dele visitou uma ilha pequena."], ["They took a boat early in the morning.", "Eles pegaram um barco de manhã cedo."], ["Ben used to be afraid of water, but he did not cry.", "Ben tinha medo de água, mas não chorou."], ["He found a shell in the sand and gave it to his mother.", "Ele achou uma concha na areia e deu para a mãe."], ["Last year, he showed the shell to his friends.", "No ano passado, ele mostrou a concha aos amigos."]], [["What did you do on the island?", "O que você fez na ilha?"], ["We walked on the sand and found shells.", "Andamos na areia e achamos conchas."], ["Did you take the boat alone?", "Você pegou o barco sozinho?"], ["No, I didn’t. My father came with me.", "Não. Meu pai foi comigo."], ["Where did you sleep?", "Onde vocês dormiram?"], ["We slept in a small hotel near the beach.", "Dormimos num hotel pequeno perto da praia."], ["Did you use to travel a lot?", "Você viajava muito?"], ["Not really. That was my first big trip.", "Nem tanto. Foi minha primeira viagem grande."]], ["Sons em shell e sand", "Em shell, o sh é “ch” suave, sem o som de t. Em sand, o s soa limpo, sem e na frente.", ["shell", "I found a shell."]], ["Ben ___ a shell on the sand.", "found", "finded", "Ben achou uma concha na areia.", "Find é irregular: o passado é found."]];
