plans[16]={"title": "Atrasado por causa do trânsito", "file": "photo-stationSign-1.webp", "grammar": "Because/so em explicações sobre o que aconteceu", "goal": "Use because para dar o motivo e so para mostrar a consequência.", "words": [["traffic", "trânsito"], ["battery", "bateria"], ["excuse", "desculpa"], ["delay", "atraso"]]};
content[16]=[[["Ravi was late because there was a lot of traffic.", "Ravi se atrasou porque havia muito trânsito."], ["He was sitting on the bus, so he could not walk.", "Ele estava no ônibus, então não podia ir a pé."], ["His phone had no battery, so he asked a woman for help.", "O celular dele estava sem bateria, então ele pediu ajuda a uma mulher."], ["She called Ava because he did not know the number.", "Ela ligou para a Ava porque ele não sabia o número."], ["Ava was not angry because the excuse was true.", "Ava não ficou brava porque a desculpa era verdadeira."]], [["Why were you late this morning?", "Por que você se atrasou hoje de manhã?"], ["I was late because there was a lot of traffic.", "Me atrasei porque havia muito trânsito."], ["Why didn’t you call me?", "Por que você não me ligou?"], ["My phone had no battery, so I could not call.", "Meu celular estava sem bateria, então não pude ligar."], ["How did you get here?", "Como você chegou aqui?"], ["A woman helped me, so I called you from her phone.", "Uma mulher me ajudou, então liguei do telefone dela."], ["Is that really your excuse?", "É essa mesmo a sua desculpa?"], ["Yes, it is true, and I am very sorry.", "Sim, é verdade, e eu sinto muito."]], ["Because: /bɪˈkɒz/", "Em because, a sílaba fraca vem primeiro e a força cai em -cause, como “bicóz”.", ["because", "I stayed because it rained."]], ["I was late ___ there was traffic.", "because", "so", "Me atrasei porque havia trânsito.", "Because introduz o motivo; so introduz o resultado."]];
patterns[16]=new RegExp("\\b(because|so)\\b","i");
themes[16]="city";
photos[16]=["photo-stationSign-1.webp", "photo-phone-1.webp"];
plans[17]={"title": "Acampando perto do rio", "file": "photo-lake-1.webp", "grammar": "Then, after that, suddenly para narrar", "goal": "Use first, then, after that e suddenly para contar uma história em ordem.", "words": [["flashlight", "lanterna"], ["campfire", "fogueira"], ["suddenly", "de repente"], ["then", "então"]]};
content[17]=[[["First, Ben and Nico put up the tent near the river.", "Primeiro, Ben e Nico montaram a barraca perto do rio."], ["Then they made a campfire and cooked some potatoes.", "Depois fizeram uma fogueira e cozinharam batatas."], ["After that, they were sitting and talking quietly.", "Depois disso, ficaram sentados conversando baixinho."], ["Suddenly, the flashlight went out, and they heard a noise.", "De repente, a lanterna apagou, e eles ouviram um barulho."], ["It was only a small dog, so they laughed.", "Era só um cachorro pequeno, então eles riram."]], [["What happened first?", "O que aconteceu primeiro?"], ["First, we put up the tent by the river.", "Primeiro, montamos a barraca perto do rio."], ["What did you do then?", "O que vocês fizeram depois?"], ["Then we made a campfire and ate dinner.", "Depois fizemos uma fogueira e jantamos."], ["What happened after that?", "O que aconteceu depois disso?"], ["Suddenly, my flashlight went out.", "De repente, minha lanterna apagou."], ["Were you afraid?", "Vocês ficaram com medo?"], ["Yes, but it was only a dog, so we laughed.", "Sim, mas era só um cachorro, então rimos."]], ["Suddenly: /ˈsʌdənli/", "Em suddenly, a força cai em SUD. O -den- é curto, quase só um d e um n: SÃ-dn-li.", ["suddenly", "Suddenly, it stopped."]], ["___, the light went out.", "Suddenly", "Sudden", "De repente, a luz apagou.", "Para modificar a frase toda, use o advérbio suddenly, com -ly."]];
patterns[17]=new RegExp("\\b(First|Then|After that|Suddenly)\\b","i");
themes[17]="park";
