plans[18]={"title": "Onde você estava às nove?", "file": "photo-ticketdesk-2.webp", "grammar": "Alibi e testemunha: where were you at nine?", "goal": "Pergunte e responda sobre onde alguém estava e o que fazia: Where were you at nine?", "words": [["thief", "ladrão"], ["witness", "testemunha"], ["detective", "detetive"], ["alibi", "álibi"]]};
content[18]=[[["Someone took Peg’s bicycle from the park at nine o’clock.", "Alguém levou a bicicleta da Peg do parque às nove horas."], ["A detective asked Tina, “Where were you at nine?”", "Um detetive perguntou à Tina: “Onde você estava às nove?”"], ["Tina said she was eating breakfast with Ben.", "Tina disse que tomava café da manhã com o Ben."], ["Ben was a witness because he was sitting next to her.", "Ben era testemunha porque estava sentado ao lado dela."], ["A boy was riding the bicycle, so the detective found the thief.", "Um menino andava na bicicleta, então o detetive achou o ladrão."]], [["Where were you at nine last night?", "Onde você estava às nove ontem à noite?"], ["I was at the library with Ava.", "Eu estava na biblioteca com a Ava."], ["What were you doing there?", "O que você fazia lá?"], ["I was studying for a test.", "Eu estudava para uma prova."], ["Was anyone with you?", "Alguém estava com você?"], ["Yes, Ava was. She is my witness.", "Sim, a Ava. Ela é minha testemunha."], ["Were you at the library at ten too?", "Você ainda estava na biblioteca às dez?"], ["Yes, we were. Ask the man at the desk.", "Estava. Pergunte ao homem da recepção."]], ["Where were you: ritmo", "Na fala rápida, Where were you soa “uér-uér-iu”. Só where e you recebem força.", ["where", "Where were you?"]], ["Where ___ you at nine?", "were", "was", "Onde você estava às nove?", "Com you, o passado de be é were."]];
patterns[18]=new RegExp("\\b[Ww]here (were|was) \\w+|\\b(was|were) \\w+ing\\b","i");
themes[18]="chat";
photos[18]=["photo-ticketdesk-2.webp", "photo-bag-1.webp"];
plans[19]={"title": "O dia do apagão", "file": "photo-dusk-1.webp", "grammar": "Revisão: passado contínuo, when, while, because e so", "goal": "Conte uma noite sem luz usando passado contínuo junto com passado simples, while, because e so.", "words": [["blackout", "apagão"], ["power", "energia"], ["dark", "escuro"], ["pot", "panela"]]};
content[19]=[[["There was a blackout in Lia’s street on Tuesday.", "Houve um apagão na rua da Lia na terça."], ["She was cooking dinner when the power went out.", "Ela preparava o jantar quando a energia acabou."], ["It was dark, so she looked for a flashlight.", "Estava escuro, então ela procurou uma lanterna."], ["Her brother was playing a game while she looked.", "O irmão dela jogava enquanto ela procurava."], ["They were not worried because they had some food.", "Eles não estavam preocupados porque tinham comida."]], [["What were you doing when the power went out?", "O que você fazia quando a energia acabou?"], ["I was cooking dinner. It was suddenly dark.", "Eu cozinhava o jantar. De repente, ficou escuro."], ["Was your brother helping you?", "Seu irmão estava ajudando você?"], ["No, he wasn’t. He was playing a game.", "Não. Ele estava jogando."], ["How long did you wait for the power?", "Quanto tempo vocês esperaram a energia?"], ["We waited two hours because the blackout was big.", "Esperamos duas horas porque o apagão foi grande."], ["Did you eat in the dark?", "Vocês jantaram no escuro?"], ["Yes, we did. We ate sandwiches.", "Sim. Comemos sanduíches."]], ["Blackout: acento na primeira sílaba", "Em blackout, a força cai em BLACK: BLÉC-aut. Em power, o som é quase uma sílaba só: “páuer”.", ["blackout", "The blackout was long."]], ["She ___ dinner when the power went out.", "was cooking", "cooked", "Ela preparava o jantar quando a energia acabou.", "A ação longa vai no contínuo, e a interrupção, no passado simples."]];
patterns[19]=new RegExp("\\b(was|were) \\w+ing\\b|\\bwhen\\b","i");
themes[19]="city";
photos[19]=["photo-dusk-1.webp", "photo-lake-2.webp"];
stories[19]=["A noite sem luz de Lia", "There was a blackout in Lia’s street on Tuesday evening.~Houve um apagão na rua da Lia na terça à noite.|She was cooking soup when the power suddenly went out.~Ela fazia sopa quando a energia acabou de repente.|It was very dark, so she asked her brother for help.~Estava muito escuro, então ela pediu ajuda ao irmão.|He was playing a game, but his phone had no battery.~Ele jogava, mas o celular estava sem bateria.|While they looked for a flashlight, someone knocked on the door.~Enquanto procuravam uma lanterna, alguém bateu à porta.|It was a neighbor, and she was holding two big candles.~Era uma vizinha, e ela segurava duas velas grandes.|They did not eat in the kitchen because it was too hot.~Eles não comeram na cozinha porque estava quente demais.|Then they sat outside and talked while the soup was cooling.~Depois sentaram lá fora e conversaram enquanto a sopa esfriava.|At eleven, the lights came back, and everybody cheered loudly.~Às onze, a luz voltou, e todos comemoraram bem alto.|Lia was tired, so she washed the pot and went to bed.~Lia estava cansada, então lavou a panela e foi dormir."];
plans[20]={"title": "Dois sofás na loja", "file": "photo-coffeeTable-1.webp", "grammar": "Comparativo curto: bigger than, cheaper than, earlier than", "goal": "Some -er ao adjetivo curto e use than para comparar duas coisas.", "words": [["couch", "sofá"], ["bargain", "pechincha"], ["living room", "sala"], ["gray", "cinza"]]};
content[20]=[[["Ravi is looking at two sofas in a store.", "Ravi está olhando dois sofás em uma loja."], ["The blue sofa is bigger than the gray one.", "O sofá azul é maior que o cinza."], ["The gray sofa is cheaper than the blue one.", "O sofá cinza é mais barato que o azul."], ["His living room is smaller than the store.", "A sala dele é menor que a loja."], ["He buys the gray couch and takes it home.", "Ele compra o sofá cinza e leva para casa."]], [["Which couch do you like more?", "De qual sofá você gosta mais?"], ["I like the blue one, but it is bigger than our room.", "Eu gosto do azul, mas ele é maior que nossa sala."], ["The gray one is smaller than the blue one.", "O cinza é menor que o azul."], ["Yes, and it is cheaper than the blue one. A bargain!", "Sim, e é mais barato que o azul. Uma pechincha!"], ["How much is the gray sofa?", "Quanto custa o sofá cinza?"], ["It is three hundred dollars, with free delivery.", "São trezentos dólares, com entrega grátis."], ["Can you bring it on Saturday morning?", "Vocês podem trazer no sábado de manhã?"], ["Yes, we can come earlier than ten o’clock.", "Sim, podemos chegar antes das dez horas."]], ["O som /ð/ em than", "Ponha a ponta da língua entre os dentes e vibre a voz, como no th de this.", ["than", "The sofa is bigger than the chair."]], ["The gray sofa is ___ than the blue one.", "cheaper", "more cheap", "O sofá cinza é mais barato que o azul.", "Adjetivo curto recebe -er: cheap vira cheaper."]];
patterns[20]=new RegExp("\\b(?:bigger|smaller|cheaper|earlier) than\\b","i");
themes[20]="city";
photos[20]=["photo-coffeeTable-1.webp", "photo-counter-1.webp"];
plans[21]={"title": "Escolhendo uma poltrona", "file": "photo-desk-1.webp", "grammar": "More + adjetivo longo: more expensive, more comfortable", "goal": "Use more antes de adjetivos longos e than para comparar, sem juntar -er.", "words": [["armchair", "poltrona"], ["modern", "moderno"], ["sit", "sentar"], ["cushion", "almofada"]]};
content[21]=[[["Tina wants a new armchair for her bedroom.", "Tina quer uma poltrona nova para o quarto dela."], ["The red armchair is more comfortable than the black one.", "A poltrona vermelha é mais confortável que a preta."], ["The black one is more modern, but it is more expensive.", "A preta é mais moderna, mas é mais cara."], ["She sits in both chairs for ten minutes.", "Ela senta nas duas poltronas por dez minutos."], ["In the end, she picks the more comfortable chair.", "No fim, ela escolhe a poltrona mais confortável."]], [["Are you ready to choose an armchair?", "Você já está pronta para escolher uma poltrona?"], ["Almost. The red one is more comfortable.", "Quase. A vermelha é mais confortável."], ["But the black one is more modern.", "Mas a preta é mais moderna."], ["True, but it is much more expensive.", "É verdade, mas é muito mais cara."], ["How much more expensive is it?", "Quanto mais cara ela é?"], ["It costs fifty dollars more than the red one.", "Custa cinquenta dólares a mais que a vermelha."], ["Then I will take the red armchair.", "Então vou levar a poltrona vermelha."], ["Great choice. Do you want delivery to your house?", "Ótima escolha. Você quer entrega em casa?"]], ["Acento em comfortable", "A sílaba forte é COM: COM-fer-ta-bol, e o meio quase some.", ["comfortable", "This bed is comfortable."]], ["The red armchair is ___ than the black one.", "more comfortable", "comfortabler", "A poltrona vermelha é mais confortável que a preta.", "Adjetivo longo usa more, não -er."]];
patterns[21]=new RegExp("\\bmore (?:comfortable|modern|expensive)\\b","i");
themes[21]="city";
