content[22]=[[["Noah and Ava read a book about mountains.", "Noah e Ava leem um livro sobre montanhas."], ["Mount Everest is the tallest mountain in the world.", "O Everest é a montanha mais alta do mundo."], ["The oldest mountain in the book is in Africa.", "A montanha mais velha do livro fica na África."], ["It also has the longest river in the story.", "Também tem o rio mais longo da história."], ["Ava wants to climb the smallest mountain first.", "Ava quer subir primeiro a menor montanha."]], [["What is the tallest mountain you know?", "Qual é a montanha mais alta que você conhece?"], ["I know Everest. It is the tallest of all.", "Eu conheço o Everest. É a mais alta de todas."], ["Is it also the oldest mountain?", "Ela também é a montanha mais velha?"], ["No, there are older mountains in other places.", "Não, há montanhas mais velhas em outros lugares."], ["Which mountain is the easiest to climb?", "Qual montanha é a mais fácil de subir?"], ["The smallest one near our town is easy.", "A menor perto da nossa cidade é fácil."], ["Do you want to climb it this weekend?", "Você quer subir nela neste fim de semana?"], ["Yes, but the weather must be the best.", "Sim, mas o tempo precisa estar o melhor possível."]], ["Final -est em tallest", "Diga /ɪst/, curto: TAL-ist, sem acento no final.", ["tallest", "She is the tallest girl here."]], ["Everest is the ___ mountain in the world.", "tallest", "most tall", "O Everest é a montanha mais alta do mundo.", "Adjetivo curto forma o superlativo com the + -est."]];
patterns[22]=new RegExp("\\bthe \\w+est\\b","i");
themes[22]="park";
photos[22]=["photo-lake-1.webp", "photo-coast-1.webp"];
plans[23]={"title": "O filme mais interessante", "file": "photo-ticketdesk-1.webp", "grammar": "The most + adjetivo longo: the most interesting", "goal": "Use the most antes de adjetivos longos para falar do extremo do grupo.", "words": [["film", "filme"], ["boring", "chato"], ["popular", "popular"], ["comedy", "comédia"]]};
content[23]=[[["Ben and Lou are at the cinema.", "Ben e Lou estão no cinema."], ["There are three films tonight, and Lou wants to choose.", "Há três filmes hoje à noite, e Lou quer escolher."], ["The space film is the most popular one.", "O filme sobre o espaço é o mais popular."], ["The old comedy is the most boring, says Ben.", "A comédia antiga é a mais chata, diz Ben."], ["They buy tickets for the most interesting film.", "Eles compram ingressos para o filme mais interessante."]], [["Which film is the most popular tonight?", "Qual filme é o mais popular hoje à noite?"], ["The space film. Everyone says it is the best.", "O filme do espaço. Todo mundo diz que é o melhor."], ["Is it also the most interesting one?", "Ele também é o mais interessante?"], ["I think so. The story is very exciting.", "Acho que sim. A história é muito emocionante."], ["What about the comedy at seven?", "E a comédia das sete?"], ["My sister says it is the most boring film.", "Minha irmã diz que é o filme mais chato."], ["Then let us watch the space film.", "Então vamos assistir ao filme do espaço."], ["Good idea. I will buy the popcorn.", "Boa ideia. Eu compro a pipoca."]], ["Acento em interesting", "Fale IN-tres-ting, com três sílabas: o meio quase desaparece.", ["interesting", "This is an interesting book."]], ["It is the ___ film of the year.", "most interesting", "interestingest", "É o filme mais interessante do ano.", "Adjetivo longo forma o superlativo com the most."]];
patterns[23]=new RegExp("\\bthe most \\w+\\b","i");
themes[23]="ticket";
photos[23]=["photo-ticketdesk-1.webp", "photo-ticketdesk-2.webp"];
plans[24]={"title": "Dois celulares parecidos", "file": "photo-phone-1.webp", "grammar": "As … as e not as … as", "goal": "Use as + adjetivo + as para dizer que são iguais e not as … as para dizer que um é menos.", "words": [["speaker", "alto-falante"], ["as good as", "tão bom quanto"], ["clear", "nítido"], ["charge", "carregar"]]};
content[24]=[[["June is comparing two phones at a small shop.", "June está comparando dois celulares em uma loja pequena."], ["The new phone has a screen as big as a book.", "O celular novo tem uma tela tão grande quanto um livro."], ["The old phone is not as heavy as the new one.", "O celular velho não é tão pesado quanto o novo."], ["Its speaker is as good as the new speaker.", "O alto-falante dele é tão bom quanto o do novo."], ["The old phone is not as expensive, so June takes it.", "O celular velho não é tão caro, então June o leva."]], [["Is the old phone as fast as the new one?", "O celular velho é tão rápido quanto o novo?"], ["Not really, but the screen is as clear.", "Não muito, mas a tela é tão nítida quanto."], ["And the speaker? Is it as good?", "E o alto-falante? É tão bom?"], ["Yes, it is as loud as the new one.", "Sim, é tão alto quanto o novo."], ["Is it as heavy as the other phone?", "É tão pesado quanto o outro celular?"], ["No, it is not as heavy. It is lighter.", "Não, não é tão pesado. É mais leve."], ["What is the price of the old phone?", "Qual é o preço do celular velho?"], ["It costs eighty dollars, not as much as the new one.", "Custa oitenta dólares, não tanto quanto o novo."]], ["Ligando as as", "Em as good as, o primeiro as é fraco e o segundo também: az-GUD-az.", ["as", "She is as tall as me."]], ["The old phone is not ___ heavy as the new one.", "as", "more", "O celular velho não é tão pesado quanto o novo.", "A comparação de igualdade usa as … as."]];
patterns[24]=new RegExp("\\bas \\w+ as\\b|\\bnot as \\w+ as\\b","i");
