plans[25]={"title": "Qual hotel é melhor", "file": "photo-luggage-1.webp", "grammar": "Comparativos irregulares: better, worse, further", "goal": "Use better, worse e further sem -er nem more, pois são formas especiais.", "words": [["better", "melhor"], ["worse", "pior"], ["further", "mais longe"], ["reserve", "reservar"]]};
content[25]=[[["Peg and Nico are choosing a hotel for the weekend.", "Peg e Nico estão escolhendo um hotel para o fim de semana."], ["The first hotel is better than the second one.", "O primeiro hotel é melhor que o segundo."], ["The second hotel has worse rooms and a worse breakfast.", "O segundo hotel tem quartos piores e um café da manhã pior."], ["But it is further from the beach than the first.", "Mas fica mais longe da praia que o primeiro."], ["They book the better hotel for two nights.", "Eles reservam o melhor hotel por duas noites."]], [["Is this hotel better than the other one?", "Este hotel é melhor que o outro?"], ["Yes, the rooms are much better.", "Sim, os quartos são muito melhores."], ["What about the food? Is it worse?", "E a comida? É pior?"], ["No, it is better, and the coffee is great.", "Não, é melhor, e o café é ótimo."], ["Is the beach further from the second hotel?", "A praia fica mais longe do segundo hotel?"], ["Yes, it is about two miles further.", "Sim, fica uns três quilômetros mais longe."], ["Then we should take the first hotel.", "Então devemos ficar com o primeiro hotel."], ["Good. I will call them right now.", "Ótimo. Vou ligar para eles agora mesmo."]], ["O som /ɛ/ em better", "Abra a boca um pouco, como no e de é em português; o t soa como um d rápido.", ["better", "This is a better plan."]], ["The first hotel is ___ than the second one.", "better", "gooder", "O primeiro hotel é melhor que o segundo.", "Good tem comparativo irregular: better."]];
patterns[25]=new RegExp("\\b(?:better|worse|further)\\b","i");
themes[25]="map";
photos[25]=["photo-luggage-1.webp", "photo-street-1.webp"];
plans[26]={"title": "Qual mochila comprar", "file": "photo-bag-1.webp", "grammar": "Comparar duas opções antes de comprar (Which is better?)", "goal": "Use Which is better? e as formas de comparação para escolher entre duas coisas.", "words": [["discount", "desconto"], ["choose", "escolher"], ["strong", "forte"], ["light", "leve"]]};
content[26]=[[["Lia needs a backpack for her school trip.", "Lia precisa de uma mochila para a viagem da escola."], ["The green backpack is lighter, but the blue one is stronger.", "A mochila verde é mais leve, mas a azul é mais forte."], ["The blue one has a bigger price, but it has a discount.", "A azul tem um preço maior, mas tem desconto."], ["Lia asks the seller which one is better for travel.", "Lia pergunta ao vendedor qual é melhor para viagem."], ["She chooses the blue backpack and pays at the counter.", "Ela escolhe a mochila azul e paga no balcão."]], [["Which backpack is better for a school trip?", "Qual mochila é melhor para uma viagem da escola?"], ["The blue one is stronger and has more pockets.", "A azul é mais forte e tem mais bolsos."], ["And the green one? Is it cheaper?", "E a verde? É mais barata?"], ["Yes, but the blue one has a discount today.", "Sim, mas a azul tem desconto hoje."], ["What is the price after the discount?", "Qual é o preço depois do desconto?"], ["It is thirty dollars, ten less than before.", "São trinta dólares, dez a menos que antes."], ["Then the blue one is the better choice.", "Então a azul é a melhor escolha."], ["I agree. You must choose one today.", "Concordo. Você precisa escolher uma hoje."]], ["O som /tʃ/ em choose", "Comece com o t e solte como em tchau: tchuz.", ["choose", "Please choose a bag."]], ["Which backpack is ___, the blue one or the green one?", "better", "more good", "Qual mochila é melhor, a azul ou a verde?", "Good vira better na comparação, nunca more good."]];
patterns[26]=new RegExp("\\b(?:better|stronger|cheaper|lighter|bigger)\\b","i");
themes[26]="cup";
photos[26]=["photo-bag-1.webp", "photo-counter-1.webp"];
plans[27]={"title": "Duas cidades, duas rotinas", "file": "photo-street-1.webp", "grammar": "Comparar cidades e lugares com adjetivos", "goal": "Use comparativos e superlativos para descrever e comparar cidades e bairros.", "words": [["parking", "estacionamento"], ["noisier", "mais barulhento"], ["bus", "ônibus"], ["crossing", "faixa de pedestres"]]};
content[27]=[[["Ravi lives in a big city, and Ben lives in a village.", "Ravi mora em uma cidade grande, e Ben mora em um vilarejo."], ["The city is noisier and more crowded than the village.", "A cidade é mais barulhenta e mais lotada que o vilarejo."], ["The parking is terrible in the morning.", "O estacionamento é terrível de manhã."], ["Ben’s village is quieter, but the shops are fewer.", "O vilarejo de Ben é mais silencioso, mas tem menos lojas."], ["Ravi visits Ben to get some quiet.", "Ravi visita Ben para ter um pouco de silêncio."]], [["Is your city more crowded than my village?", "Sua cidade é mais lotada que o meu vilarejo?"], ["Yes, it is much noisier, too.", "Sim, é muito mais barulhenta também."], ["How is the parking in the morning?", "Como é o estacionamento de manhã?"], ["Terrible. The buses are the most crowded.", "Terrível. Os ônibus são os mais lotados."], ["Here it is quieter, but there is less to do.", "Aqui é mais silencioso, mas há menos o que fazer."], ["I like quiet places more than busy ones.", "Eu gosto mais de lugares silenciosos que movimentados."], ["Then come to the village next weekend.", "Então venha ao vilarejo no próximo fim de semana."], ["Thanks. I will take the early train.", "Obrigado. Vou pegar o trem da manhã."]], ["O som /ɔɪ/ em noisy", "Comece com o de óleo e termine com i: NÓI-zi.", ["noisy", "The street is very noisy."]], ["The city is ___ than the village.", "more crowded", "crowdeder", "A cidade é mais lotada que o vilarejo.", "Crowded é um adjetivo longo para comparar: more crowded."]];
patterns[27]=new RegExp("\\b(?:noisier|quieter|more crowded|most crowded|less)\\b","i");
