plans[28]={"title": "Corrida no parque", "file": "photo-parkPath-1.webp", "grammar": "Advérbios comparativos: faster, more slowly, better", "goal": "Use faster, harder, better ou more + advérbio com than para comparar como as pessoas fazem algo.", "words": [["breathe", "respirar"], ["harder", "com mais esforço"], ["deeply", "fundo"], ["wet", "molhado"]]};
content[28]=[[["Noah and Tina run in the park every Sunday.", "Noah e Tina correm no parque todo domingo."], ["Tina runs faster than Noah, but he runs longer.", "Tina corre mais rápido que Noah, mas ele corre por mais tempo."], ["Noah starts slowly and finishes more strongly than Tina.", "Noah começa devagar e termina com mais força que Tina."], ["Today he wants to train harder than last week.", "Hoje ele quer treinar com mais esforço que na semana passada."], ["Tina tells him to run more carefully on wet grass.", "Tina diz a ele para correr com mais cuidado na grama molhada."]], [["Why do you always run faster than me?", "Por que você sempre corre mais rápido que eu?"], ["I start more slowly, but I do not stop.", "Eu começo mais devagar, mas não paro."], ["Maybe I should start slowly, too.", "Talvez eu devesse começar devagar também."], ["Yes, and breathe more deeply than before.", "Sim, e respire mais fundo que antes."], ["Can you run as fast as Peg?", "Você consegue correr tão rápido quanto a Peg?"], ["No, she runs much better than both of us.", "Não, ela corre muito melhor que nós dois."], ["Then we should train harder this month.", "Então devemos treinar com mais esforço neste mês."], ["Good. Let us meet earlier next Sunday.", "Ótimo. Vamos nos encontrar mais cedo no próximo domingo."]], ["Final -ly em slowly", "Diga SLOU-li e termine com um i curto, sem soprar o l.", ["slowly", "Please speak slowly."]], ["Tina runs ___ than Noah.", "faster", "more fast", "Tina corre mais rápido que Noah.", "Fast é advérbio curto: faster, sem more."]];
patterns[28]=new RegExp("\\b(?:faster|harder|better|earlier|more (?:slowly|carefully|strongly|deeply))\\b","i");
themes[28]="park";
photos[28]=["photo-parkPath-1.webp", "photo-walk-1.webp"];
plans[29]={"title": "Qual academia escolher", "file": "photo-clock-1.webp", "grammar": "Revisão: escolher o melhor plano (mini-história)", "goal": "Revise comparativos, superlativos e as ... as ao escolher entre três planos de academia.", "words": [["member", "sócio"], ["trainer", "treinador"], ["monthly", "mensal"], ["yearly", "anual"]]};
content[29]=[[["Lou wants to join a gym near his office.", "Lou quer entrar em uma academia perto do escritório dele."], ["The first gym is cheaper, but the second is bigger.", "A primeira academia é mais barata, mas a segunda é maior."], ["The third gym has the best trainer in town.", "A terceira academia tem o melhor treinador da cidade."], ["A monthly plan is not as expensive as a yearly plan.", "Um plano mensal não é tão caro quanto um anual."], ["Lou becomes a member of the third gym.", "Lou se torna sócio da terceira academia."]], [["Which gym is the cheapest in town?", "Qual academia é a mais barata da cidade?"], ["The first one. It is cheaper than the others.", "A primeira. É mais barata que as outras."], ["Is it as good as the third gym?", "Ela é tão boa quanto a terceira academia?"], ["No, the third gym has better machines.", "Não, a terceira tem aparelhos melhores."], ["And the trainer? Is he more helpful?", "E o treinador? Ele ajuda mais?"], ["Yes, he is the most helpful person there.", "Sim, ele é a pessoa mais prestativa de lá."], ["How much is a monthly plan for members?", "Quanto custa o plano mensal para sócios?"], ["Forty dollars. That is a fair price.", "Quarenta dólares. É um preço justo."]], ["Acento em member", "Fale MEM-ber, com força no começo e o final fraco.", ["member", "He is a gym member."]], ["The third gym has the ___ trainer in town.", "best", "most good", "A terceira academia tem o melhor treinador da cidade.", "Good tem superlativo irregular: the best."]];
patterns[29]=new RegExp("\\b(?:cheaper|bigger|better|best|cheapest|most helpful|as \\w+ as)\\b","i");
themes[29]="health";
photos[29]=["photo-board-1.webp", "photo-desk-1.webp"];
stories[29]=["Lou escolhe sua academia", "Lou wanted to start exercising after a long winter.~Lou queria começar a se exercitar depois de um longo inverno.|He visited three gyms near his office on Monday.~Ele visitou três academias perto do escritório na segunda-feira.|The first gym was cheaper than the other two.~A primeira academia era mais barata que as outras duas.|The second gym was bigger, but it was very crowded.~A segunda academia era maior, mas estava muito lotada.|The third gym was quieter and had the best trainer.~A terceira academia era mais silenciosa e tinha o melhor treinador.|Lou asked if a monthly plan was as expensive as a yearly one.~Lou perguntou se um plano mensal era tão caro quanto um anual.|The trainer smiled and showed him the cheapest monthly plan.~O treinador sorriu e mostrou a ele o plano mensal mais barato.|Lou compared the three prices on his phone that night.~Lou comparou os três preços no celular naquela noite.|In the end, he chose the third gym, the most helpful one.~No fim, ele escolheu a terceira academia, a mais prestativa.|Now he trains harder and sleeps better than before.~Agora ele treina com mais esforço e dorme melhor que antes."];
plans[30]={"title": "Dor de cabeça no trabalho", "file": "photo-hospital-1.webp", "grammar": "Should e shouldn’t para dar conselhos", "goal": "Use should + verbo para aconselhar e shouldn’t + verbo para aconselhar contra algo.", "words": [["advice", "conselho"], ["break", "pausa"], ["hour", "hora"], ["work", "trabalho"]]};
content[30]=[[["Ava has a headache after a long day at work.", "Ava está com dor de cabeça depois de um longo dia de trabalho."], ["Her friend June says she should rest for an hour.", "A amiga June diz que ela deve descansar por uma hora."], ["She also says Ava shouldn’t look at the screen.", "Ela também diz que Ava não deve olhar para a tela."], ["Ava should drink more water and eat something.", "Ava deve beber mais água e comer alguma coisa."], ["She follows the advice and feels better soon.", "Ela segue o conselho e logo se sente melhor."]], [["I have a headache. What should I do?", "Estou com dor de cabeça. O que devo fazer?"], ["You should rest and drink some water.", "Você deve descansar e beber um pouco de água."], ["Should I take a pill?", "Devo tomar um comprimido?"], ["Maybe, but you shouldn’t take two.", "Talvez, mas você não deve tomar dois."], ["Should I go back to my computer?", "Devo voltar para o computador?"], ["No, you shouldn’t. Your eyes need a break.", "Não, não deve. Seus olhos precisam de uma pausa."], ["Thanks for the advice, June.", "Obrigada pelo conselho, June."], ["Anytime. Call me if it gets worse.", "Quando quiser. Me ligue se piorar."]], ["Final -n’t em shouldn’t", "O d é mudo: diga SHU-dnt, com o n e o t bem curtos.", ["shouldn’t", "You shouldn’t run."]], ["You ___ rest after work.", "should", "should to", "Você deve descansar depois do trabalho.", "Should vem direto antes do verbo, sem to."]];
patterns[30]=new RegExp("\\bshould(?:n\u2019t)?\\b","i");
themes[30]="health";
