content[31]=[[["Nico gets a new bike for his birthday.", "Nico ganha uma bicicleta nova no aniversário."], ["His father explains the rules of the road to him.", "O pai explica a ele as regras de trânsito."], ["Nico must wear a helmet every time he rides.", "Nico deve usar capacete toda vez que andar."], ["He must stop at a red light, and he mustn’t ride on the sidewalk.", "Ele deve parar no sinal vermelho e não pode andar na calçada."], ["Nico promises to follow every rule.", "Nico promete seguir todas as regras."]], [["What are the rules for my new bike?", "Quais são as regras para minha bicicleta nova?"], ["You must wear a helmet every day.", "Você deve usar capacete todos os dias."], ["Must I wear it for a short ride, too?", "Preciso usar mesmo em um passeio curto?"], ["Yes, you must. It is the first rule.", "Sim, precisa. É a primeira regra."], ["What must I do at a red light?", "O que devo fazer no sinal vermelho?"], ["You must stop and wait for green.", "Você deve parar e esperar o verde."], ["Can I ride on the sidewalk?", "Posso andar na calçada?"], ["No, you mustn’t. It is dangerous for people.", "Não, não pode. É perigoso para as pessoas."]], ["O som /ʌ/ em must", "Boca relaxada, som curto entre a e ó: MAST.", ["must", "You must stop here."]], ["You ___ ride on the sidewalk.", "mustn’t", "must", "Você não pode andar na calçada.", "Mustn’t indica proibição; must sozinho obriga."]];
