content[32]=[[["Peg starts her first job at a coffee shop.", "Peg começa seu primeiro emprego em uma cafeteria."], ["She has to wear a uniform and a green apron.", "Ela tem que usar uniforme e um avental verde."], ["Her shift starts at seven, so she has to wake up early.", "O turno dela começa às sete, então ela precisa acordar cedo."], ["She doesn’t have to clean the floor, because Sam does that.", "Ela não precisa limpar o chão, porque o Sam faz isso."], ["Every customer has to hear a friendly hello.", "Todo cliente precisa ouvir um olá simpático."]], [["Do I have to wear a uniform?", "Eu tenho que usar uniforme?"], ["Yes, you have to wear it every shift.", "Sim, tem que usar em todo turno."], ["Do I have to bring my own apron?", "Preciso trazer meu próprio avental?"], ["No, you don’t have to. We give you one.", "Não, não precisa. Nós damos um a você."], ["What time do I have to arrive?", "A que horas preciso chegar?"], ["You have to be here at a quarter to seven.", "Você tem que estar aqui às seis e quinze."], ["Do I have to stay late on Fridays?", "Preciso ficar até tarde às sextas?"], ["Only sometimes, and you don’t have to say yes.", "Só às vezes, e você não precisa dizer sim."]], ["Have to soa como hafta", "Em have to, o v soa como f: HAF-tu, bem ligado.", ["have to", "I have to work today."]], ["She ___ wear a uniform today.", "has to", "have to", "Ela tem que usar uniforme hoje.", "Com she, use has to."]];
patterns[32]=new RegExp("\\b(?:has|have|had)? ?(?:don\u2019t|doesn\u2019t)? ?have to\\b|\\bhas to\\b","i");
