plans[33]={"title": "Pedidos educados no escritório", "file": "photo-desk-1.webp", "grammar": "Can e could para pedidos educados (Could you…?)", "goal": "Use Could you + verbo para pedir algo de forma educada; Can you é mais informal.", "words": [["lend", "emprestar"], ["favor", "favor"], ["copy", "copiar"], ["stapler", "grampeador"]]};
content[33]=[[["Ben is busy at his desk at the office.", "Ben está ocupado na mesa dele no escritório."], ["He needs a stapler, so he asks June for help.", "Ele precisa de um grampeador, então pede ajuda a June."], ["Could you lend me yours for a minute?", "Você poderia me emprestar o seu por um minuto?"], ["June says yes and asks him for a favor.", "June diz que sim e pede um favor a ele."], ["Could he copy the report for the meeting?", "Ele poderia copiar o relatório para a reunião?"]], [["Could you lend me your stapler, please?", "Você poderia me emprestar seu grampeador, por favor?"], ["Of course. Here it is.", "Claro. Aqui está."], ["Could I ask you a favor, too?", "Eu poderia pedir um favor também?"], ["Sure. What do you need?", "Claro. O que você precisa?"], ["Could you copy this report for me?", "Você poderia copiar este relatório para mim?"], ["Yes. How many copies do you want?", "Sim. Quantas cópias você quer?"], ["Can you make ten, please?", "Pode fazer dez, por favor?"], ["Of course, I will bring them to the meeting room.", "Claro, vou levá-las para a sala de reuniões."]], ["Entonação do pedido educado", "Em Could you…?, a voz sobe no final, como numa pergunta de sim ou não.", ["could", "Could you help me?"]], ["___ you lend me a pen, please?", "Could", "Do", "Você poderia me emprestar uma caneta, por favor?", "Could you + verbo é o pedido educado."]];
patterns[33]=new RegExp("\\b(?:Could|Can) (?:you|I|he)\\b","i");
