content[34]=[[["Lia is in class, and the room is very hot.", "Lia está na aula, e a sala está muito quente."], ["She asks the teacher, “May I open the window?”", "Ela pergunta à professora: Posso abrir a janela?"], ["The teacher gives her permission to open it.", "A professora dá permissão para ela abrir."], ["Later, Lia needs to leave early for a doctor visit.", "Mais tarde, Lia precisa sair cedo para ir ao médico."], ["Is it OK if she leaves at three?", "Tudo bem se ela sair às três?"]], [["May I open the window, please?", "Posso abrir a janela, por favor?"], ["Yes, you may. It is very hot today.", "Sim, pode. Está muito quente hoje."], ["Is it OK if I leave early?", "Tudo bem se eu sair mais cedo?"], ["What time do you need to leave?", "A que horas você precisa sair?"], ["At three. I have a doctor visit.", "Às três. Tenho consulta médica."], ["That is fine. Do you have permission from home?", "Tudo bem. Você tem permissão de casa?"], ["Yes, my mother sent a note.", "Sim, minha mãe mandou um bilhete."], ["Good. May I see it, please?", "Ótimo. Posso ver, por favor?"]], ["O som /eɪ/ em may", "Comece em é e termine em i: mêi, com a boca abrindo pouco.", ["may", "May I come in?"]], ["___ I open the window?", "May", "Do", "Posso abrir a janela?", "May I + verbo é o pedido de permissão."]];
