plans[37]={"title": "Quando eu era criança", "file": "photo-lake-2.webp", "grammar": "Could para habilidade no passado e can para presente", "goal": "Use could para o que você conseguia fazer no passado e can para o que consegue hoje.", "words": [["climb", "escalar"], ["jump", "pular"], ["lake", "lago"], ["tree", "árvore"]]};
content[37]=[[["Noah looks at an old photo of his family.", "Noah olha uma foto antiga da família dele."], ["When he was six, he could swim across the lake.", "Quando tinha seis anos, ele conseguia nadar pelo lago."], ["He could also climb tall trees, but he can’t climb now.", "Ele também conseguia escalar árvores altas, mas agora não consegue."], ["His sister couldn’t jump high then, but she can now.", "A irmã dele não sabia pular alto, mas agora sabe."], ["Noah can still swim, and he practices every week.", "Noah ainda sabe nadar, e treina toda semana."]], [["Could you swim when you were six?", "Você sabia nadar quando tinha seis anos?"], ["Yes, I could swim very well.", "Sim, eu nadava muito bem."], ["Could you climb trees, too?", "Você também conseguia subir em árvores?"], ["Yes, but I can’t climb them now.", "Sim, mas agora não consigo."], ["Could your sister jump high then?", "Sua irmã sabia pular alto na época?"], ["No, she couldn’t, but she can now.", "Não, não sabia, mas agora sabe."], ["Can you still swim every week?", "Você ainda nada toda semana?"], ["Yes, I can. I love the water.", "Sim. Eu adoro a água."]], ["Can e can’t", "Can é fraco, quase kun; can’t é forte, com o a aberto como em cat.", ["can’t", "I can’t swim."]], ["When I was six, I ___ swim across the lake.", "could", "can", "Quando eu tinha seis anos, eu conseguia nadar pelo lago.", "Para habilidade no passado, use could."]];
