plans[38]={"title": "O que fazer no domingo", "file": "photo-friends-1.webp", "grammar": "Why don’t you…? e How about…? para sugerir", "goal": "Use Why don’t you + verbo e How about + verbo com -ing para fazer sugestões.", "words": [["suggest", "sugerir"], ["river", "rio"], ["near", "perto"], ["boat ride", "passeio de barco"]]};
content[38]=[[["Ben and Ava do not know what to do on Sunday.", "Ben e Ava não sabem o que fazer no domingo."], ["Ava suggests, “Why don’t we visit the museum?”", "Ava sugere: Por que não visitamos o museu?"], ["Ben says, “How about taking a boat ride first?”", "Ben diz: Que tal um passeio de barco primeiro?"], ["Why don’t you ask Lia to join us for lunch?", "Por que você não convida a Lia para almoçar com a gente?"], ["They agree on a plan, and Ava calls Lia.", "Eles combinam um plano, e Ava liga para a Lia."]], [["What should we do on Sunday?", "O que devemos fazer no domingo?"], ["Why don’t we visit the museum?", "Por que não visitamos o museu?"], ["Good idea. How about a boat ride first?", "Boa ideia. Que tal um passeio de barco primeiro?"], ["Great. How about having lunch near the river?", "Ótimo. Que tal almoçar perto do rio?"], ["Why don’t you ask Lia to come, too?", "Por que você não convida a Lia também?"], ["I suggest we call her now.", "Sugiro que a gente ligue para ela agora."], ["Does she like boats?", "Ela gosta de barcos?"], ["Yes, she loves them. She will say yes.", "Sim, ela adora. Ela vai dizer sim."]], ["Entonação das sugestões", "Em Why don’t you…?, a voz sobe no fim; em How about…?, sobe em about.", ["suggest", "I suggest a walk."]], ["How about ___ the river?", "visiting", "visit", "Que tal visitar o rio?", "How about é seguido de verbo com -ing."]];
