plans[39]={"title": "Primeira semana no emprego", "file": "photo-desk-1.webp", "grammar": "Revisão: regras e conselhos em um novo emprego (mini-história)", "goal": "Revise should, must, have to, could e may em uma história sobre o primeiro emprego.", "words": [["manager", "gerente"], ["training", "treinamento"], ["badge", "crachá"], ["lunch break", "pausa para o almoço"]]};
content[39]=[[["Mina starts a new job at a small office.", "Mina começa um emprego novo em um escritório pequeno."], ["The manager says she must wear her badge all day.", "O gerente diz que ela deve usar o crachá o dia todo."], ["She has to finish her training before Friday.", "Ela tem que terminar o treinamento antes de sexta."], ["She should take a lunch break at noon.", "Ela deve fazer a pausa para o almoço ao meio-dia."], ["She doesn’t have to stay late on the first week.", "Ela não precisa ficar até tarde na primeira semana."]], [["Could you tell me the rules, please?", "Você poderia me dizer as regras, por favor?"], ["Sure. You must wear your badge at all times.", "Claro. Você deve usar o crachá o tempo todo."], ["Do I have to finish the training this week?", "Tenho que terminar o treinamento esta semana?"], ["Yes, you do. It is only two hours.", "Sim. São só duas horas."], ["What should I do at lunch?", "O que devo fazer no almoço?"], ["You should take a lunch break at noon.", "Você deve fazer a pausa para o almoço ao meio-dia."], ["May I leave early on Friday?", "Posso sair mais cedo na sexta?"], ["Yes, you may. You don’t have to stay late.", "Sim, pode. Você não precisa ficar até tarde."]], ["Acento em manager", "A sílaba forte é MAN: MA-ni-djer, com o g soando como dj.", ["manager", "My manager is nice."]], ["You ___ wear your badge at all times.", "must", "must to", "Você deve usar o crachá o tempo todo.", "Must vem direto antes do verbo, sem to."]];
patterns[39]=new RegExp("\\b(?:must|should|have to|has to|may|could)\\b","i");
themes[39]="chat";
photos[39]=["photo-desk-1.webp", "photo-board-1.webp"];
stories[39]=["Mina e seu primeiro emprego", "Mina was nervous on her first morning at the new office.~Mina estava nervosa na primeira manhã no escritório novo.|The manager said she must wear her badge all day.~O gerente disse que ela deve usar o crachá o dia todo.|She had to finish her training before the end of the week.~Ela tinha que terminar o treinamento antes do fim da semana.|A coworker told her she should ask questions when needed.~Uma colega disse que ela deve fazer perguntas quando precisar.|Mina could not find the printer, so she asked for help.~Mina não achou a impressora, então pediu ajuda.|May I use this one, or is it broken?~Posso usar esta, ou ela está quebrada?|Her coworker laughed and said she could use any printer.~A colega riu e disse que ela podia usar qualquer impressora.|At noon, Mina took her lunch break and called her mother.~Ao meio-dia, Mina fez a pausa e ligou para a mãe.|She did not have to stay late, so she went home.~Ela não precisou ficar até tarde, então foi para casa.|By Friday, Mina knew the rules and felt much better.~Na sexta, Mina conhecia as regras e se sentia bem melhor."];
