content[40]=[[["Look at those dark clouds over the park.", "Olhe aquelas nuvens escuras sobre o parque."], ["Ravi says it is going to rain soon.", "Ravi diz que vai chover logo."], ["Lia is going to open her red umbrella.", "Lia vai abrir o guarda-chuva vermelho."], ["They are going to wait under a big tree.", "Eles vão esperar embaixo de uma árvore grande."], ["After the storm, they are going to jump over a big puddle.", "Depois da tempestade, eles vão pular sobre uma grande poça."]], [["Are you going to walk home today?", "Você vai voltar a pé para casa hoje?"], ["No, I am not. It is going to rain.", "Não. Vai chover."], ["How do you know? The sky looks fine.", "Como você sabe? O céu parece bom."], ["I can hear thunder behind the hills.", "Estou ouvindo trovão atrás dos morros."], ["Is Ben going to bring an umbrella?", "O Ben vai trazer um guarda-chuva?"], ["He is going to bring two, I think.", "Ele vai trazer dois, eu acho."], ["What are we going to do after school?", "O que vamos fazer depois da escola?"], ["We are going to wait at my aunt’s house.", "Vamos esperar na casa da minha tia."]], ["Som de th em thunder", "Ponha a língua entre os dentes e solte o ar sem vibrar a voz; não diga tander.", ["thunder", "The thunder is very loud."]], ["The sky is black. It ___ rain.", "is going to", "going to", "O céu está preto. Vai chover.", "Com be going to, o verbo be (is) vem antes de going to."]];
