content[41]=[[["Tina is seeing the dentist on Friday morning.", "Tina vai ao dentista na sexta de manhã."], ["Her appointment is at nine thirty.", "A consulta dela é às nove e meia."], ["Her brother is driving her to the clinic.", "O irmão dela vai levá-la de carro à clínica."], ["They are leaving the house at nine.", "Eles saem de casa às nove."], ["Tina is not working on Friday afternoon.", "Tina não vai trabalhar na sexta à tarde."]], [["What are you doing on Friday morning?", "O que você vai fazer na sexta de manhã?"], ["I am seeing the dentist at nine thirty.", "Vou ao dentista às nove e meia."], ["Oh, is someone driving you there?", "Ah, alguém vai levar você?"], ["Yes, my brother is taking me.", "Sim, meu irmão vai me levar."], ["Is he staying with you at the clinic?", "Ele vai ficar com você na clínica?"], ["No, he is meeting a friend nearby.", "Não, ele vai encontrar um amigo por perto."], ["Are you free for lunch after that?", "Você está livre para almoçar depois?"], ["Yes, I am. I have a reminder on my phone.", "Sim. Tenho um lembrete no celular."]], ["Acento em appointment", "Acentue a segunda sílaba: apPOINTment. O oi soa como em boy.", ["appointment", "I have an appointment at ten."]], ["Tomorrow I ___ my dentist at ten.", "am seeing", "see", "Amanhã vou ao meu dentista às dez.", "Para um compromisso marcado, use o present continuous com am/is/are + -ing."]];
