content[42]=[[["Noah opens the menu at a small restaurant.", "Noah abre o cardápio em um restaurante pequeno."], ["The waiter says the soup is very good today.", "O garçom diz que a sopa está muito boa hoje."], ["Noah thinks for a minute and says, “I will order it.”", "Noah pensa um minuto e diz: “Vou pedir.”"], ["Peg wants something light, so she will have a salad.", "Peg quer algo leve, então vai comer uma salada."], ["At the end, Noah will pay the bill.", "No fim, o Noah vai pagar a conta."]], [["Do you know what you want to eat?", "Você sabe o que quer comer?"], ["Not yet. Wait, the soup looks nice.", "Ainda não. Espere, a sopa parece boa."], ["I think I will try the chicken soup.", "Acho que vou provar a sopa de frango."], ["Good idea. I will have the fish.", "Boa ideia. Eu vou comer o peixe."], ["Excuse me, we are ready to order now.", "Com licença, estamos prontos para pedir agora."], ["Of course. Do you need a fork or a spoon?", "Claro. Precisam de garfo ou de colher?"], ["I will use a spoon for the soup.", "Eu vou usar uma colher para a sopa."], ["Great. I will bring the bill after lunch.", "Ótimo. Trago a conta depois do almoço."]], ["Som de w em waiter", "Arredonde os lábios como para dizer u e abra rápido; não diga vaiter.", ["waiter", "The waiter is very kind."]], ["The soup looks nice. I think I ___ it.", "will try", "am try", "A sopa parece boa. Acho que vou provar.", "Uma decisão tomada na hora usa will + verbo base."]];
