plans[43]={"title": "Uma promessa sobre o segredo", "file": "photo-friends-1.webp", "grammar": "Will not / won’t para recusas e promessas", "goal": "Use will not ou won’t para recusar algo e para prometer que você não vai fazer algo.", "words": [["promise", "promessa"], ["secret", "segredo"], ["lie", "mentir"], ["truth", "verdade"]]};
content[43]=[[["Ava has a big secret about her birthday party.", "A Ava tem um grande segredo sobre a festa de aniversário dela."], ["She tells Nico, and he makes a promise.", "Ela conta ao Nico, e ele faz uma promessa."], ["“I will not tell anyone,” he says.", "“Não vou contar a ninguém”, ele diz."], ["Later, Ben asks questions, but Nico won’t talk.", "Depois, o Ben faz perguntas, mas o Nico não fala."], ["Nico will not lie, so he just smiles.", "O Nico não vai mentir, então só sorri."]], [["Can you keep a secret for me?", "Você pode guardar um segredo para mim?"], ["Yes, I promise I won’t tell anyone.", "Sim, prometo que não vou contar a ninguém."], ["Not even Ben? He asks a lot of questions.", "Nem para o Ben? Ele faz muitas perguntas."], ["I will not say a word to him.", "Não vou dizer uma palavra a ele."], ["What if he gets angry with you?", "E se ele ficar bravo com você?"], ["He won’t be angry for long. He is my friend.", "Ele não vai ficar bravo por muito tempo. É meu amigo."], ["Will you lie to him, then?", "Então você vai mentir para ele?"], ["No, I won’t. I will just change the subject.", "Não. Só vou mudar de assunto."]], ["Won’t não rima com don’t", "Won’t soa como “uônt”, com o ô longo. Não diga “uon”.", ["won’t", "I won’t tell anyone."]], ["I promise I ___ tell anyone.", "won’t", "not will", "Prometo que não vou contar a ninguém.", "Para prometer ou recusar, use will not ou won’t + verbo base."]];
patterns[43]=new RegExp("\\b(?:won\u2019t|will not)\\b","i");
