plans[47]={"title": "Talvez um piquenique no lago", "file": "photo-lake-2.webp", "grammar": "Might para planos incertos: I might go", "goal": "Use might + verbo para falar de algo que talvez aconteça, quando você ainda não tem certeza.", "words": [["might", "talvez (verbo)"], ["grass", "grama"], ["ant", "formiga"], ["shade", "sombra"]]};
content[47]=[[["Noah and Tina might have a picnic by the lake.", "Noah e Tina talvez façam um piquenique no lago."], ["Maybe they will bring sandwiches and juice.", "Talvez levem sanduíches e suco."], ["Tina might take a blanket from home.", "A Tina talvez leve um cobertor de casa."], ["Noah might not come if it is cloudy.", "O Noah talvez não vá se estiver nublado."], ["It might be a nice day after all.", "Talvez seja um bom dia, afinal."]], [["Are you free on Saturday afternoon?", "Você está livre no sábado à tarde?"], ["I might be. Why do you ask?", "Talvez. Por que pergunta?"], ["We might have a picnic by the lake.", "Talvez a gente faça um piquenique no lago."], ["That sounds great. Who is coming?", "Parece ótimo. Quem vem?"], ["Noah might come, but he is not sure.", "O Noah talvez venha, mas não tem certeza."], ["I might bring a basket with some fruit.", "Talvez eu leve uma cesta com frutas."], ["Maybe we can sit on the grass too.", "Talvez a gente possa sentar na grama também."], ["Good idea. I might bring my cards.", "Boa ideia. Talvez eu leve minhas cartas."]], ["Som de i em might", "O gh é mudo. Diga “máit”, como em night e light.", ["might", "I might go to the lake."]], ["I ___ go to the lake on Saturday.", "might", "might to", "Talvez eu vá ao lago no sábado.", "Might é seguido direto do verbo base, sem to."]];
