plans[49]={"title": "Mudando para uma cidade nova", "file": "photo-luggage-1.webp", "grammar": "Revisão: planos, previsões, promessas e pedidos sobre o futuro", "goal": "Revise be going to, will, might e as expressões de tempo contando como Lia vai se mudar para outra cidade.", "words": [["apartment", "apartamento"], ["moving truck", "caminhão de mudança"], ["rent", "alugar"], ["landlord", "proprietário"]]};
content[49]=[[["Lia is moving to a new city next month.", "A Lia vai se mudar para uma cidade nova no mês que vem."], ["Her apartment is on the fifth floor, with an elevator.", "O apartamento dela fica no quinto andar, com elevador."], ["Ravi is going to drive the moving truck.", "O Ravi vai dirigir o caminhão de mudança."], ["He will probably arrive at her new address by noon.", "Ele provavelmente vai chegar ao novo endereço dela ao meio-dia."], ["Lia might paint the kitchen, but she is not sure.", "A Lia talvez pinte a cozinha, mas não tem certeza."]], [["Where are you going to live in the new city?", "Onde você vai morar na cidade nova?"], ["I am going to rent an apartment near the park.", "Vou alugar um apartamento perto do parque."], ["Will you send me your new address soon?", "Você me manda seu novo endereço em breve?"], ["Yes, I will write it down tomorrow.", "Sim, vou anotá-lo amanhã."], ["Is there an elevator in the building?", "Tem elevador no prédio?"], ["Yes, there is, so the boxes won’t be a problem.", "Tem, então as caixas não vão ser problema."], ["When is the moving truck going to arrive?", "Quando o caminhão de mudança vai chegar?"], ["It will definitely arrive on Saturday morning.", "Com certeza chega no sábado de manhã."]], ["Acento em apartment", "Acentue a segunda sílaba: aPARTment. O a inicial é fraco, quase um é.", ["apartment", "My apartment is on the second floor."]], ["The truck ___ arrive on Saturday morning.", "is going to", "going to", "O caminhão vai chegar no sábado de manhã.", "Be going to precisa de am/is/are antes."]];
patterns[49]=new RegExp("\\b(?:is|am|are) (?:not )?going to\\b|\\bwill\\b","i");
themes[49]="city";
photos[49]=["photo-luggage-1.webp", "photo-ticketdesk-1.webp"];
stories[49]=["Lia muda de cidade", "Lia is going to move to a new city next month.~Lia vai se mudar para uma cidade nova no mês que vem.|She has a small apartment waiting near a quiet park.~Ela tem um apartamento pequeno esperando perto de um parque tranquilo.|Ravi promises he will help her with all the boxes.~Ravi promete que vai ajudá-la com todas as caixas.|On Saturday morning, the moving truck is not at the door.~No sábado de manhã, o caminhão de mudança não está na porta.|Lia is worried, and she calls Ravi on her phone.~Lia fica preocupada e liga para o Ravi no celular.|He says the truck will probably arrive in an hour.~Ele diz que o caminhão provavelmente chega em uma hora.|It is going to rain, so they cover the boxes.~Vai chover, então eles cobrem as caixas.|Finally, the truck arrives, and the elevator works well.~Por fim, o caminhão chega, e o elevador funciona bem.|By night, Lia is going to sleep in her new bed.~À noite, a Lia vai dormir na cama nova.|Tomorrow she will send her new address to everyone.~Amanhã ela vai mandar o novo endereço para todos."];
plans[50]={"title": "Lugares que eu já visitei", "file": "photo-square-1.webp", "grammar": "Have/has + particípio: experiências (I have visited…)", "goal": "Use have ou has + particípio passado para falar de experiências na vida, sem dizer quando elas aconteceram.", "words": [["castle", "castelo"], ["sushi", "sushi"], ["horse", "cavalo"], ["skate", "patinar"]]};
content[50]=[[["Ben has visited a castle in the north.", "O Ben já visitou um castelo no norte."], ["He has also ridden a horse on the beach.", "Ele também já andou a cavalo na praia."], ["His friend Ava has tried sushi many times.", "A amiga dele, Ava, já provou sushi muitas vezes."], ["They have learned to skate on the lake.", "Eles já aprenderam a patinar no lago."], ["Now they have many stories to tell.", "Agora eles têm muitas histórias para contar."]], [["Where have you traveled in your life?", "Onde você já viajou na vida?"], ["I have visited a castle in Scotland.", "Eu já visitei um castelo na Escócia."], ["Wow! Have you seen the horses there?", "Nossa! Você viu os cavalos lá?"], ["Yes, I have ridden one for an hour.", "Sim, andei em um por uma hora."], ["My sister has tried sushi, but I have not.", "Minha irmã já provou sushi, mas eu não."], ["Then we have to go to a sushi bar.", "Então temos que ir a um restaurante de sushi."], ["Has your brother learned to skate yet?", "Seu irmão já aprendeu a patinar?"], ["He has, and he is really good now.", "Já, e agora ele é muito bom."]], ["Som de h em has e have", "O h é soprado, com o ar saindo da garganta; não é o r do português.", ["have", "I have a big family."]], ["I ___ a castle in Scotland.", "have visited", "visit have", "Eu já visitei um castelo na Escócia.", "A experiência usa have + particípio passado (visited)."]];
