content[51]=[[["Peg has never seen a volcano.", "A Peg nunca viu um vulcão."], ["Her uncle has seen one in Italy.", "O tio dela já viu um na Itália."], ["Noah has never touched a snake at the zoo.", "O Noah nunca tocou numa cobra no zoológico."], ["Peg has been to a circus once, as a child.", "A Peg já foi a um circo uma vez, quando criança."], ["Neither of them has ever jumped with a parachute.", "Nenhum dos dois jamais pulou de paraquedas."]], [["Have you ever seen a volcano?", "Você já viu um vulcão alguma vez?"], ["No, I have never seen one. Have you?", "Não, nunca vi um. E você?"], ["My uncle has, but I have not.", "Meu tio já viu, mas eu não."], ["Have you ever touched a snake?", "Você já tocou numa cobra alguma vez?"], ["Never! I am afraid of them.", "Nunca! Tenho medo delas."], ["Have you ever gone to a circus?", "Você já foi a um circo alguma vez?"], ["Yes, once. I saw a clown with a dog.", "Sim, uma vez. Vi um palhaço com um cachorro."], ["I have never used a parachute, but I would like to.", "Nunca usei paraquedas, mas gostaria."]], ["Entonação em Have you ever…?", "A voz sobe no final. Ever soa como “ÉV-er”, com o v bem marcado.", ["ever", "Have you ever seen snow?"]], ["Have you ___ seen a volcano?", "ever", "never", "Você já viu um vulcão alguma vez?", "Em perguntas usamos ever; never aparece nas respostas negativas."]];
