content[52]=[[["Ava’s parents are coming for dinner at seven.", "Os pais da Ava vêm jantar às sete."], ["She has already washed the laundry.", "Ela já lavou a roupa."], ["She has already taken out the trash.", "Ela já levou o lixo para fora."], ["But she has not cleaned the living room yet.", "Mas ela ainda não limpou a sala."], ["Nico has not finished the cake yet either.", "O Nico também ainda não terminou o bolo."]], [["Have you cleaned the house yet?", "Você já limpou a casa?"], ["I have already done the laundry.", "Eu já lavei a roupa."], ["Good. Have you taken out the trash yet?", "Bom. Você já levou o lixo para fora?"], ["Yes, I have already done that too.", "Sim, também já fiz isso."], ["What about the living room floor?", "E o chão da sala?"], ["I have not started to sweep it yet.", "Ainda não comecei a varrê-lo."], ["Hurry up! Use the bucket and the mop.", "Depressa! Use o balde e o esfregão."], ["Do not worry. It will take ten minutes.", "Não se preocupe. Vai levar dez minutos."]], ["Palavra already", "Acentue a segunda sílaba: alREdy. O r é suave, como em hora.", ["already", "I have already eaten."]], ["I have ___ cleaned the kitchen.", "already", "yet", "Eu já limpei a cozinha.", "Already vai em frases afirmativas; yet vai em perguntas e negativas."]];
