content[53]=[[["Tina has just left the shop with a new shirt.", "A Tina acabou de sair da loja com uma camisa nova."], ["Then she checks her arm and stops.", "Então ela olha o braço e para."], ["Her purse has just disappeared.", "A bolsa dela acabou de sumir."], ["She runs back and asks about it at the counter.", "Ela volta correndo e pergunta no balcão."], ["The cashier has just found it under a chair.", "A caixa acabou de encontrá-la debaixo de uma cadeira."]], [["Excuse me, I have just lost my purse.", "Com licença, acabei de perder minha bolsa."], ["Oh no. When did you last have it?", "Ah, não. Quando foi a última vez que a viu?"], ["I paid here five minutes ago.", "Paguei aqui há cinco minutos."], ["Is it black? A woman has just found one.", "É preta? Uma mulher acabou de achar uma."], ["Yes! It has my name inside.", "Sim! Tem meu nome dentro."], ["Here it is. Please check your money.", "Aqui está. Por favor, confira seu dinheiro."], ["Everything is here, even the coins and the zipper is fine.", "Está tudo aqui, até as moedas, e o zíper está bom."], ["You are lucky. I have just cleaned that chair.", "Você tem sorte. Acabei de limpar aquela cadeira."]], ["Som de j em just", "Comece com d e solte o som de j: “djâst”. Não diga “iast”.", ["just", "I have just arrived."]], ["She ___ just found her keys.", "has", "have", "Ela acabou de encontrar as chaves.", "She usa has; just fica entre has e o particípio."]];
