content[54]=[[["June has played the violin for three years.", "A June toca violino há três anos."], ["She has been in the school choir since March.", "Ela está no coro da escola desde março."], ["Her teacher has known her since she was ten.", "A professora a conhece desde que ela tinha dez anos."], ["Lou has practiced with her for two weeks.", "O Lou ensaia com ela há duas semanas."], ["They have lived on the same street since 2020.", "Eles moram na mesma rua desde 2020."]], [["How long have you played the violin?", "Há quanto tempo você toca violino?"], ["I have played it for three years.", "Toco há três anos."], ["Are you in a choir too?", "Você também está em um coro?"], ["Yes, I have sung there since March.", "Sim, canto lá desde março."], ["Has your teacher taught you for a long time?", "Sua professora ensina você há muito tempo?"], ["She has taught me since I was ten.", "Ela me ensina desde que eu tinha dez anos."], ["Do you practice every day?", "Você pratica todos os dias?"], ["Yes, I have practiced for an hour today.", "Sim, hoje pratiquei por uma hora."]], ["Som de v em violin", "Encoste os dentes de cima no lábio de baixo, com vibração: vaiolín.", ["violin", "She plays the violin."]], ["I have lived here ___ 2020.", "since", "for", "Moro aqui desde 2020.", "Since vem com um ponto no tempo (2020); for vem com um período."]];
