content[55]=[[["Nico has been to a big valley in Brazil.", "O Nico já esteve em uma grande vale no Brasil."], ["He has never been to a desert.", "Ele nunca esteve em um deserto."], ["Tina is not home. She has gone to the old temple.", "A Tina não está em casa. Ela foi ao templo velho."], ["Her brother has gone to a cave with friends.", "O irmão dela foi a uma caverna com amigos."], ["They have not come back yet.", "Eles ainda não voltaram."]], [["Have you ever been to a valley?", "Você já foi a uma vale?"], ["Yes, I have been to one in Brazil.", "Sim, já fui a uma no Brasil."], ["Have you been to a desert too?", "Você também já foi a um deserto?"], ["No, I have never been to one.", "Não, nunca fui a um."], ["Where is Tina? Her phone is here.", "Cadê a Tina? O celular dela está aqui."], ["She has gone to the old temple.", "Ela foi até o templo velho."], ["And her brother? Is he with her?", "E o irmão dela? Está com ela?"], ["No, he has gone to a cave with friends.", "Não, ele foi a uma caverna com amigos."]], ["Been com som de bin", "Nos Estados Unidos, been costuma soar como “bin”, com i curto.", ["been", "I have been to Rio."]], ["Tina is not here. She has ___ to the temple.", "gone", "been", "Tina não está aqui. Ela foi até o templo.", "Gone to quer dizer que a pessoa ainda não voltou; been to quer dizer que já voltou."]];
