content[56]=[[["Ben has seen a famous musician in concert.", "O Ben já viu uma música famosa em um show."], ["He saw her last year at a big stadium.", "Ele a viu no ano passado em um grande estádio."], ["The audience sang every song with her.", "A plateia cantou todas as músicas com ela."], ["Ava has never been to a stadium show.", "A Ava nunca foi a um show em estádio."], ["She wanted to go in 2022, but she was sick.", "Ela quis ir em 2022, mas estava doente."]], [["Have you ever seen a musician in concert?", "Você já viu um músico em um show?"], ["Yes, I saw one last year.", "Sim, vi um no ano passado."], ["Where did you see the musician?", "Onde você viu o músico?"], ["At the stadium near the river.", "No estádio perto do rio."], ["Was the audience very big?", "A plateia era muito grande?"], ["Yes! People sang with the microphone too.", "Sim! O pessoal cantou com o microfone também."], ["I have never been to a stadium show.", "Nunca fui a um show de estádio."], ["You should go next time. It was amazing.", "Você deveria ir da próxima vez. Foi incrível."]], ["Passado de saw e see", "Saw soa como “só”, com o som aberto. Não confunda com see (si).", ["saw", "I saw a musician last year."]], ["I ___ a musician last year.", "saw", "have seen", "Eu vi um músico no ano passado.", "Com last year, que marca um tempo passado, use o passado simples."]];
