content[57]=[[["Tina has a hamster in a small cage.", "A Tina tem um hamster em uma gaiola pequena."], ["She has had it for two years.", "Ela tem o hamster há dois anos."], ["Her friend Lou has a goldfish in the kitchen.", "O amigo dela, Lou, tem um peixinho dourado na cozinha."], ["He has had the goldfish since his birthday.", "Ele tem o peixinho desde o aniversário dele."], ["Tina and Lou have known each other for years.", "Tina e Lou se conhecem há anos."]], [["Do you have a pet at home?", "Você tem um bichinho em casa?"], ["Yes, I have a hamster named Coco.", "Sim, tenho um hamster chamado Coco."], ["How long have you had him?", "Há quanto tempo você o tem?"], ["I have had him for two years.", "Tenho ele há dois anos."], ["Does he live in a big cage?", "Ele mora em uma gaiola grande?"], ["Yes, and he runs on a wheel all night.", "Sim, e corre na roda a noite toda."], ["How long have you known Lou?", "Há quanto tempo você conhece o Lou?"], ["We have known each other since school.", "Nós nos conhecemos desde a escola."]], ["Entonação em How long", "A voz cai no final da pergunta com palavra de pergunta. Long soa como “lóng”.", ["long", "How long have you lived here?"]], ["How long ___ you had a hamster?", "have", "do", "Há quanto tempo você tem um hamster?", "How long pede have/has + particípio para um estado que continua."]];
