plans[58]={"title": "Lista do que já fiz", "file": "photo-desk-1.webp", "grammar": "Particípios irregulares frequentes: seen, done, eaten, written", "goal": "Aprenda os particípios irregulares seen, done, eaten, written e gone e use-os com have/has.", "words": [["novel", "romance"], ["letter", "carta"], ["pasta", "pasta"], ["statue", "estátua"]]};
content[58]=[[["Noah has written a letter to his grandmother.", "O Noah escreveu uma carta para a avó."], ["He has also done all his homework today.", "Ele também já fez toda a lição de casa hoje."], ["Peg has eaten pasta three times this week.", "A Peg comeu pasta três vezes nesta semana."], ["She has seen a beautiful statue at school.", "Ela viu uma estátua linda na escola."], ["Now she has read half of a new novel.", "Agora ela leu metade de um romance novo."]], [["What have you done this morning?", "O que você fez nesta manhã?"], ["I have written a long letter.", "Escrevi uma carta longa."], ["Who is it for? Have you sent it?", "Para quem é? Você já a enviou?"], ["It is for my grandmother. Not yet.", "É para minha avó. Ainda não."], ["Have you eaten anything today?", "Você comeu alguma coisa hoje?"], ["Yes, I have eaten pasta for lunch.", "Sim, comi pasta no almoço."], ["Have you seen the new statue upstairs?", "Você viu a nova estátua lá em cima?"], ["Yes, I have, and I love the colors.", "Vi sim, e adoro as cores."]], ["Particípio eaten", "Diga “ÍTen”, com o t suave e a vogal curta no final. Não é “eiten”.", ["eaten", "I have eaten pasta."]], ["She has ___ a letter to her mother.", "written", "wrote", "Ela escreveu uma carta para a mãe.", "Com has, use o particípio written; wrote é o passado simples."]];
patterns[58]=new RegExp("\\b(?:have|has) (?:also |not )?(?:written|done|eaten|seen|read)\\b","i");
themes[58]="notebook";
photos[58]=["photo-desk-1.webp", "photo-book-1.webp"];
plans[59]={"title": "Uma entrevista sobre experiências", "file": "photo-desk-1.webp", "grammar": "Revisão: presente perfeito, ever/never, already/yet, just, for/since", "goal": "Revise o presente perfeito numa entrevista de emprego, com experiências, ever, never, just, for e since.", "words": [["interview", "entrevista"], ["owner", "dona"], ["experience", "experiência"], ["skill", "habilidade"]]};
content[59]=[[["Ava has an interview at a bookstore today.", "A Ava tem uma entrevista em uma livraria hoje."], ["The owner asks about her work experience.", "A dona pergunta sobre a experiência de trabalho dela."], ["Ava has worked in a cafe for two years.", "A Ava trabalha em um café há dois anos."], ["She has never sold books, but she learns fast.", "Ela nunca vendeu livros, mas aprende rápido."], ["The owner has just offered her the job.", "A dona acabou de oferecer o emprego a ela."]], [["Have you ever worked in a store?", "Você já trabalhou em uma loja?"], ["Yes, I have worked in a cafe for two years.", "Sim, trabalho em um café há dois anos."], ["What skill is your best one?", "Qual é a sua melhor habilidade?"], ["I have always been good with people.", "Sempre me dei bem com as pessoas."], ["Have you ever sold books before?", "Você já vendeu livros antes?"], ["No, I have never done that.", "Não, nunca fiz isso."], ["Have you read many novels this year?", "Você leu muitos romances neste ano?"], ["Yes, I have read ten since January.", "Sim, li dez desde janeiro."]], ["Acento em interview", "Acentue a primeira sílaba: ÍNterview. O t soa suave, quase d.", ["interview", "I have an interview today."]], ["I have worked here ___ two years.", "for", "since", "Trabalho aqui há dois anos.", "For vem com um período de tempo (two years)."]];
patterns[59]=new RegExp("\\b(?:have|has) (?:never |just |always )?[a-z]+(?:ed|en|ne|rn|ld|ad|ne)\\b","i");
themes[59]="chat";
photos[59]=["photo-desk-1.webp", "photo-deskStudy-1.webp"];
stories[59]=["A entrevista da Ava", "Ava has wanted to work in a bookstore for years.~A Ava quer trabalhar em uma livraria há anos.|Today she has an interview with the owner at ten.~Hoje ela tem uma entrevista com a dona às dez.|She has already read her notes three times this morning.~Ela já leu as anotações três vezes esta manhã.|At the door, she has just realized her phone is missing.~Na porta, ela acabou de perceber que o celular sumiu.|The owner smiles and asks, “Have you ever worked with books?”~A dona sorri e pergunta: “Você já trabalhou com livros?”|Ava says she has never sold books but has read many.~A Ava diz que nunca vendeu livros, mas já leu muitos.|She has worked in a cafe since she was eighteen.~Ela trabalha em um café desde os dezoito anos.|The owner has seen many people, but Ava feels honest.~A dona já viu muita gente, mas a Ava parece sincera.|Then Ava finds her phone in her jacket pocket.~Então a Ava acha o celular no bolso do casaco.|The owner laughs and says, “You have the job.”~A dona ri e diz: “O emprego é seu.”"];
plans[60]={"title": "O vizinho do piano", "file": "photo-street-1.webp", "grammar": "Who para pessoas: the man who works here", "goal": "Use who depois de man, woman, people e girl para dizer de qual pessoa você fala.", "words": [["piano", "piano"], ["concert", "concerto"], ["balcony", "varanda"], ["lady", "senhora"]]};
content[60]=[[["Ben has a neighbor who plays the piano.", "Ben tem um vizinho que toca piano."], ["He is the man who lives next to the park.", "Ele é o homem que mora ao lado do parque."], ["Every evening, the man who plays the piano sits outside.", "Toda noite, o homem que toca piano senta lá fora."], ["Ben likes people who play music at night.", "Ben gosta de gente que toca música à noite."], ["Tonight a girl who sings comes to the concert.", "Hoje à noite uma garota que canta vem ao concerto."]], [["Do you know the man who plays the piano?", "Você conhece o homem que toca piano?"], ["Yes, he is the neighbor who lives in number five.", "Sim, ele é o vizinho que mora no número cinco."], ["Is he the one who has a red car?", "Ele é aquele que tem um carro vermelho?"], ["No, that is the woman who works at the bank.", "Não, essa é a mulher que trabalha no banco."], ["Who is the girl who sings with him?", "Quem é a garota que canta com ele?"], ["She is his sister, who visits every weekend.", "Ela é a irmã dele, que visita todo fim de semana."], ["Do you like neighbors who make music?", "Você gosta de vizinhos que fazem música?"], ["I do, but I like people who stop at ten.", "Gosto, mas prefiro quem para às dez."]], ["O som /w/ em who e woman", "Em who, o w quase não aparece: diga /hu/. Em woman, arredonde os lábios para o /w/.", ["who", "The man who plays is my neighbor."]], ["Ben likes the neighbor ___ plays the piano.", "who", "which", "Ben gosta do vizinho que toca piano.", "Para pessoas, use who depois do substantivo."]];
patterns[60]=new RegExp("(man|woman|neighbor|girl|people|neighbors|one|sister),? who\\b","i");
themes[60]="chat";
photos[60]=["photo-street-1.webp", "photo-door-1.webp"];
plans[61]={"title": "O celular que eu comprei", "file": "photo-phone-1.webp", "grammar": "Which para coisas: the phone which I bought", "goal": "Use which depois de phone, bag e book para dizer de qual coisa você fala.", "words": [["charger", "carregador"], ["camera", "câmera"], ["wire", "fio"], ["plug", "tomada"]]};
content[61]=[[["Mia loves the phone which she bought last week.", "Mia adora o celular que ela comprou semana passada."], ["The camera, which is very good, takes every photo well.", "A câmera, que é muito boa, tira bem cada foto."], ["The battery, which lasts two days, is her favorite part.", "A bateria, que dura dois dias, é a parte favorita dela."], ["But the charger which came in the box is too short.", "Mas o carregador que veio na caixa é curto demais."], ["She goes back to the shop which sells better chargers.", "Ela volta à loja que vende carregadores melhores."]], [["Is that the phone which you bought online?", "Esse é o celular que você comprou on-line?"], ["No, I bought it in the shop which is near the station.", "Não, comprei na loja que fica perto da estação."], ["Which charger do you use at home?", "Qual carregador você usa em casa?"], ["I use the charger which has a long wire.", "Uso o carregador que tem um fio longo."], ["Is the camera which you have easy to use?", "A câmera que você tem é fácil de usar?"], ["Yes, it is the best camera which I have ever had.", "Sim, é a melhor câmera que eu já tive."], ["Does the battery which you have last all day?", "A bateria que você tem dura o dia todo?"], ["Yes, I only plug it in at night.", "Sim, só ligo na tomada à noite."]], ["O som /tʃ/ em charger e which", "Em which o som é /w/, sem o /tʃ/. Em charger, comece com a língua no céu da boca: /tʃ/.", ["charger", "The charger is in my bag."]], ["The phone ___ I bought is very fast.", "which", "who", "O celular que eu comprei é muito rápido.", "Para coisas, use which, não who."]];
patterns[61]=new RegExp("(phone|screen|battery|charger|shop|one|camera|wire)s?,? which\\b|\\bwhich (I|she|you|has|sells|came)\\b","i");
themes[61]="notebook";
