plans[62]={"title": "A encomenda que chegou", "file": "photo-door-1.webp", "grammar": "That para pessoas e coisas", "goal": "Use that no lugar de who ou which para falar de pessoas e coisas.", "words": [["package", "pacote"], ["delivery", "entrega"], ["tape", "fita adesiva"], ["parcel", "encomenda"]]};
content[62]=[[["Ravi waits for a package that comes today.", "Ravi espera um pacote que chega hoje."], ["The delivery man that brings it is always late.", "O entregador que traz o pacote sempre atrasa."], ["The address that Ravi gave is on the box.", "O endereço que Ravi informou está na caixa."], ["It is a gift that his mother sent.", "É um presente que a mãe dele mandou."], ["The woman that lives upstairs takes the package.", "A mulher que mora no andar de cima recebe o pacote."]], [["Is this the package that you wanted?", "Esse é o pacote que você queria?"], ["Yes, it is the one that came from Boston.", "Sim, é o que veio de Boston."], ["Who is the man that brought it?", "Quem é o homem que trouxe?"], ["He is the delivery man that works in our street.", "Ele é o entregador que trabalha na nossa rua."], ["Is that the right address that you gave him?", "Esse é o endereço certo que você deu a ele?"], ["Yes, but he went to the wrong house first.", "Sim, mas ele foi primeiro à casa errada."], ["Is it a book that you ordered?", "É um livro que você pediu?"], ["No, it is a lamp that my aunt sent.", "Não, é uma luminária que minha tia mandou."]], ["O som /ð/ em that", "Ponha a ponta da língua entre os dentes e faça vibrar a voz: /ðæt/.", ["that", "That is the package that I want."]], ["The man ___ brought the box is my neighbor.", "that", "what", "O homem que trouxe a caixa é meu vizinho.", "Depois de man ou box, use that (ou who). Não use what."]];
patterns[62]=new RegExp("(package|man|one|address|gift|woman|book|lamp|box) that\\b","i");
