content[63]=[[["Peg shows Lou the village where she grew up.", "Peg mostra a Lou a vila onde ela cresceu."], ["This is the house where her family lived for years.", "Esta é a casa onde a família dela morou por anos."], ["The garage where her father fixed bikes is still there.", "A garagem onde o pai dela consertava bicicletas ainda existe."], ["Behind it is the yard where she played every day.", "Atrás dela fica o quintal onde ela brincava todo dia."], ["Now it is a place where children from the street meet.", "Hoje é um lugar onde as crianças da rua se encontram."]], [["Is this the village where you were born?", "Esta é a vila onde você nasceu?"], ["No, I was born in a town where there is a big lake.", "Não, nasci numa cidade onde há um lago grande."], ["Is there a shop where we can buy water?", "Tem uma loja onde a gente possa comprar água?"], ["Yes, there is a small one where my aunt works.", "Tem, uma pequena onde minha tia trabalha."], ["Can you show me the hall where the party is?", "Pode me mostrar o salão onde é a festa?"], ["Of course. It is the building where the old school was.", "Claro. É o prédio onde ficava a escola antiga."], ["Is that the yard where your dog sleeps?", "Esse é o quintal onde seu cachorro dorme?"], ["Yes, it is the only place where he feels safe.", "Sim, é o único lugar onde ele se sente seguro."]], ["O som /w/ + /ɛr/ em where", "Arredonde os lábios para o /w/ e termine com um /ɛr/ aberto, sem o r forte do português.", ["where", "This is where I live."]], ["This is the garage ___ my father works.", "where", "who", "Esta é a garagem onde meu pai trabalha.", "Para lugares, use where depois do substantivo."]];
patterns[63]=new RegExp("(village|house|garage|yard|place|town|shop|one|hall|building) where\\b","i");
