plans[64]={"title": "Muito trânsito, pouca gente", "file": "photo-street-1.webp", "grammar": "Quantificadores: much, many, a few, a little, plenty of", "goal": "Use much e many em perguntas e negativas, a few e a little para quantidades pequenas, plenty of para bastante.", "words": [["furniture", "móveis"], ["plenty", "bastante"], ["roof", "telhado"], ["attic", "sótão"]]};
content[64]=[[["June moves to a new flat in the city.", "June se muda para um apartamento novo na cidade."], ["There is a lot of traffic, but not much noise inside.", "Há muito trânsito, mas não muito barulho lá dentro."], ["She has a little furniture and plenty of space.", "Ela tem poucos móveis e bastante espaço."], ["A few friends come to help with the boxes.", "Alguns amigos vêm ajudar com as caixas."], ["There are not many chairs, so they sit on the floor.", "Não há muitas cadeiras, então eles sentam no chão."]], [["How much furniture do you have?", "Quanta mobília você tem?"], ["Only a little. I have a bed and a table.", "Só um pouco. Tenho uma cama e uma mesa."], ["Are there many people in your building?", "Há muita gente no seu prédio?"], ["No, only a few families live here.", "Não, só algumas famílias moram aqui."], ["Is there much traffic on your street?", "Tem muito trânsito na sua rua?"], ["Not much, but there is a crowd near the station.", "Não muito, mas há uma multidão perto da estação."], ["Do you have plenty of time today?", "Você tem bastante tempo hoje?"], ["Yes, I have plenty of time until six.", "Tenho, tenho bastante tempo até as seis."]], ["Acento em many e much", "Em many, diga /ˈmɛni/ com o e aberto. Em much, a vogal é curta, como /mʌtʃ/.", ["many", "How many chairs are there?"]], ["There are not ___ chairs in the room.", "many", "much", "Não há muitas cadeiras no quarto.", "Chairs é contável: use many, não much."]];
patterns[64]=new RegExp("\\b(much|many|a few|a little|plenty of)\\b","i");
