plans[65]={"title": "Pequeno demais, grande o bastante", "file": "photo-clinic-1.webp", "grammar": "Too e enough: too cold, big enough", "goal": "Use too antes de adjetivos para dizer excesso e enough depois de adjetivos para dizer suficiente.", "words": [["skirt", "saia"], ["tight", "apertado"], ["sleeve", "manga"], ["sock", "meia"]]};
content[65]=[[["Ava tries on a skirt in a small shop.", "Ava experimenta uma saia numa loja pequena."], ["It is too tight, so she asks for a bigger size.", "Está apertada demais, então ela pede um tamanho maior."], ["The next skirt is long enough, but too expensive.", "A saia seguinte é longa o bastante, mas cara demais."], ["At home, the new couch is too big for the room.", "Em casa, o sofá novo é grande demais para a sala."], ["Her brother says the door is not wide enough.", "O irmão dela diz que a porta não é larga o bastante."]], [["Is this skirt long enough for you?", "Esta saia é longa o bastante para você?"], ["No, it is too short. Do you have a longer one?", "Não, é curta demais. Tem uma mais longa?"], ["Yes, this one is long enough and not too tight.", "Tem, esta é longa o bastante e não é apertada demais."], ["Great. Is it too expensive for a student?", "Ótimo. É cara demais para um estudante?"], ["It is thirty dollars. Is that cheap enough?", "São trinta dólares. É barato o bastante?"], ["Yes, I think so. I will take it.", "Sim, acho que sim. Vou levar."], ["Is the couch too heavy to move alone?", "O sofá é pesado demais para mover sozinho?"], ["Yes, we need two people. It is not light enough.", "É, precisamos de duas pessoas. Não é leve o bastante."]], ["Acento em enough e too", "Em enough, o gh soa como /f/: /ɪˈnʌf/. Em too, alongue o /uː/.", ["enough", "This is big enough."]], ["The couch is ___ for our small room.", "too big", "big too", "O sofá é grande demais para nossa sala pequena.", "Too vem antes do adjetivo; enough vem depois."]];
patterns[65]=new RegExp("\\btoo \\w+|\\w+ enough\\b","i");
