plans[66]={"title": "A carteira que sumiu", "file": "photo-counter-2.webp", "grammar": "Pronomes indefinidos: someone, anything, nobody, everywhere", "goal": "Use someone, anything, nobody e everywhere para falar de pessoas, coisas e lugares sem dar nomes.", "words": [["keys", "chaves"], ["somewhere", "em algum lugar"], ["nobody", "ninguém"], ["coin", "moeda"]]};
content[66]=[[["Noah cannot find his wallet anywhere.", "Noah não acha sua carteira em lugar nenhum."], ["He looks everywhere, but he sees nothing on the table.", "Ele procura em todo lugar, mas não vê nada na mesa."], ["Someone knocks on the door and holds up some keys.", "Alguém bate à porta e mostra algumas chaves."], ["Nobody knows whose keys they are, so Noah smiles.", "Ninguém sabe de quem são as chaves, então Noah sorri."], ["His wallet is somewhere in the car, he thinks.", "A carteira dele está em algum lugar do carro, ele acha."]], [["Is there anything in your bag?", "Tem alguma coisa na sua bolsa?"], ["No, nothing. My wallet is not here.", "Não, nada. Minha carteira não está aqui."], ["Did you look everywhere in the house?", "Você procurou em toda a casa?"], ["Yes, and nobody has seen it.", "Sim, e ninguém viu."], ["Maybe someone took it by mistake.", "Talvez alguém tenha levado por engano."], ["Is there anyone at home who can check?", "Tem alguém em casa que possa conferir?"], ["Yes, my sister is there. I will call her.", "Tem, minha irmã está lá. Vou ligar para ela."], ["Good. Tell me if she finds anything.", "Ótimo. Me avise se ela achar alguma coisa."]], ["Acento em some- e any-", "Nas palavras someone, anything e everywhere, a primeira sílaba é a mais forte.", ["someone", "Someone is at the door."]], ["I cannot find my keys ___.", "anywhere", "nowhere", "Não consigo achar minhas chaves em lugar nenhum.", "Com cannot, use anywhere; nowhere já é negativo."]];
patterns[66]=new RegExp("\\b(someone|anyone|anything|nobody|nothing|everywhere|anywhere|somewhere|everyone|something)\\b","i");
