content[67]=[[["Tina cuts the bread and hurts herself with the knife.", "Tina corta o pão e se machuca com a faca."], ["She looks at herself in the mirror and laughs.", "Ela se olha no espelho e ri."], ["Her brothers burn themselves on the hot pan.", "Os irmãos dela se queimam na panela quente."], ["Tina tells them, \"Please be careful with yourselves.\"", "Tina diz: \"Por favor, cuidem-se.\""], ["They all make dinner by themselves tonight.", "Eles todos fazem o jantar sozinhos hoje."]], [["Did you hurt yourself in the kitchen?", "Você se machucou na cozinha?"], ["Yes, I cut myself with a small knife.", "Sim, eu me cortei com uma faca pequena."], ["Please look at yourself in the mirror.", "Olhe-se no espelho, por favor."], ["I am fine. Look, it is only a small cut.", "Estou bem. Veja, é só um corte pequeno."], ["Do the children cook by themselves?", "As crianças cozinham sozinhas?"], ["Sometimes. They make eggs for themselves.", "Às vezes. Fazem ovos para si mesmas."], ["Does Ben cut his own hair?", "O Ben corta o próprio cabelo?"], ["Yes, he cuts it himself every month.", "Sim, ele mesmo corta todo mês."]], ["O som /ð/ em themselves", "Ponha a língua entre os dentes no começo: /ðəmˈsɛlvz/. Termine com o /vz/ bem suave.", ["themselves", "They help themselves."]], ["Be careful, or you will hurt ___.", "yourself", "you", "Cuidado, ou você vai se machucar.", "Quando o sujeito age sobre si mesmo, use yourself."]];
patterns[67]=new RegExp("\\b(myself|yourself|himself|herself|themselves|ourselves|yourselves)\\b","i");
