content[68]=[[["Lou and Nico look at the menu together.", "Lou e Nico olham o cardápio juntos."], ["Both like chicken, but neither wants rice today.", "Os dois gostam de frango, mas nenhum quer arroz hoje."], ["Lou can have either soup or a small salad.", "Lou pode pedir sopa ou uma salada pequena."], ["For dessert, both choose the chocolate cake.", "De sobremesa, os dois escolhem o bolo de chocolate."], ["Neither of them drinks coffee at night.", "Nenhum dos dois toma café à noite."]], [["Do you want tea or coffee?", "Você quer chá ou café?"], ["Either is fine. I like both.", "Qualquer um serve. Gosto dos dois."], ["Which cake do you want, the chocolate or the apple one?", "Qual bolo você quer, o de chocolate ou o de maçã?"], ["Neither, thanks. I am not hungry.", "Nenhum dos dois, obrigado. Não estou com fome."], ["Both of these chickens look great.", "Os dois frangos parecem ótimos."], ["Then we can take either one.", "Então podemos levar qualquer um."], ["Does either of you want chocolate?", "Algum de vocês quer chocolate?"], ["Both of us do, please.", "Nós dois queremos, por favor."]], ["Duas formas de either e neither", "Nos Estados Unidos, either e neither começam com o som /i/: /ˈiðər/ e /ˈniðər/.", ["either", "Either is fine."]], ["I like tea and coffee. I like ___ of them.", "both", "either", "Eu gosto de chá e de café. Gosto dos dois.", "Both significa os dois juntos."]];
patterns[68]=new RegExp("\\b(both|either|neither)\\b","i");
themes[68]="cup";
