content[69]=[[["Mia goes to the theater where her cousin works.", "Mia vai ao teatro onde o primo dela trabalha."], ["He is the actor who plays the king in the show.", "Ele é o ator que faz o rei na peça."], ["The costume which he wears is red and heavy.", "A fantasia que ele usa é vermelha e bem pesada."], ["On the stage that they built, he looks like a king.", "No palco que eles construíram, ele parece um rei de verdade."], ["Later, Mia finds him in the hall where friends wait.", "Depois, Mia o encontra no salão onde os amigos esperam."]], [["Is this the theater where you work?", "Este é o teatro onde você trabalha?"], ["Yes, and that is the stage where I speak.", "Sim, e aquele é o palco onde eu falo."], ["Who is the actor that plays the king?", "Quem é o ator que faz o rei?"], ["He is the tall man who wears the red costume.", "É o homem alto que usa a fantasia vermelha."], ["Is that the costume which you made?", "É a fantasia que você fez?"], ["No, my aunt made it. She is a woman who loves sewing.", "Não, minha tia fez. Ela é uma mulher que adora costurar."], ["Are there seats where I can see well?", "Há lugares onde eu consiga ver bem?"], ["Yes, take the seat that is near the stage.", "Sim, pegue o lugar que fica perto do palco."]], ["Acento em actor e theater", "Em actor, a força está na primeira sílaba: /ˈæktər/. Em theater, o th inicial é /θ/ com a língua entre os dentes.", ["actor", "The actor is on stage."]], ["He is the actor ___ plays the king.", "who", "where", "Ele é o ator que faz o rei.", "Para pessoas, use who; where é para lugares."]];
patterns[69]=new RegExp("\\b(who|which|that|where) \\w+","i");
themes[69]="city";
photos[69]=["photo-ticketdesk-1.webp", "photo-square-1.webp"];
stories[69]=["O teatro da Mia", "Mia is a girl who loves the theater.~Mia é uma garota que adora o teatro.|Her cousin Sam is an actor who works every night.~O primo Sam é um ator que trabalha toda noite.|Tonight she goes to the theater where he plays a king.~Hoje à noite ela vai ao teatro onde ele faz um rei.|The man that sits next to her has a loud phone.~O homem que senta ao lado dela tem um celular barulhento.|It rings during the quiet scene which everyone loves.~Ele toca na cena silenciosa que todos adoram.|Mia asks the woman who works there for help.~Mia pede ajuda à mulher que trabalha lá.|She takes the phone to the hall where people wait.~Ela leva o celular ao salão onde as pessoas esperam.|After the show, Sam thanks the girl who helped.~Depois da peça, Sam agradece à garota que ajudou.|He shows her the costume which he wears on stage.~Ele mostra a ela a fantasia que usa no palco.|Mia smiles because it is the best night that she has had.~Mia sorri porque é a melhor noite que ela já teve."];
plans[70]={"title": "Planos para estudar", "file": "photo-study-1.webp", "grammar": "Verbo + infinitivo: want, hope, decide, plan", "goal": "Use want, hope, decide e plan seguidos de to + verbo para falar de desejos e planos.", "words": [["exam", "prova"], ["degree", "diploma"], ["course", "curso"], ["tutor", "professor particular"]]};
content[70]=[[["Nico wants to pass the exam in June.", "Nico quer passar na prova em junho."], ["He decides to study every night after dinner.", "Ele decide estudar toda noite depois do jantar."], ["He hopes to get a degree in three years.", "Ele espera conseguir um diploma em três anos."], ["His sister plans to take an online course too.", "A irmã dele pretende fazer um curso on-line também."], ["They both promise to help each other with homework.", "Os dois prometem se ajudar com a lição de casa."]], [["What do you want to study next year?", "O que você quer estudar no ano que vem?"], ["I hope to study art, but I have not decided yet.", "Espero estudar arte, mas ainda não decidi."], ["Do you plan to take the exam this spring?", "Você pretende fazer a prova nesta primavera?"], ["Yes, I plan to ask a tutor for help.", "Sim, pretendo pedir ajuda a um professor particular."], ["Did your brother decide to join the course?", "Seu irmão decidiu entrar no curso?"], ["Yes, he wants to learn French before the trip.", "Sim, ele quer aprender francês antes da viagem."], ["Do you hope to live abroad one day?", "Você espera morar no exterior um dia?"], ["I do, and I want to start soon.", "Espero, e quero começar logo."]], ["Reduzindo to em want to", "Na fala rápida, want to soa como wanna: o to vira um /tə/ curto e fraco.", ["want", "I want to study."]], ["Nico decides ___ every night.", "to study", "studying", "Nico decide estudar toda noite.", "Depois de decide, use to + verbo."]];
patterns[70]=new RegExp("\\b(want|wants|hope|hopes|decide|decides|decided|plan|plans) to\\b","i");
themes[70]="notebook";
photos[70]=["photo-study-1.webp", "photo-deskStudy-1.webp"];
plans[71]={"title": "Terminando a pintura", "file": "photo-door-1.webp", "grammar": "Verbo + -ing: enjoy, finish, mind, keep", "goal": "Use enjoy, finish, mind e keep seguidos de verbo com -ing.", "words": [["repair", "consertar"], ["ladder", "escada de mão"], ["hammer", "martelo"], ["drill", "furadeira"]]};
content[71]=[[["Ben enjoys painting the old fence on Saturdays.", "Ben gosta de pintar a cerca velha aos sábados."], ["He finishes painting the door before the rain starts.", "Ele termina de pintar a porta antes da chuva começar."], ["Then he keeps working and starts to repair the roof.", "Depois ele continua trabalhando e começa a consertar o telhado."], ["His neighbor does not mind lending a ladder.", "O vizinho dele não se importa de emprestar uma escada."], ["By six, Ben is tired but he enjoys looking at the house.", "Às seis, Ben está cansado, mas gosta de olhar para a casa."]], [["Do you enjoy painting walls?", "Você gosta de pintar paredes?"], ["Yes, but I do not enjoy cleaning the brush.", "Gosto, mas não gosto de limpar o pincel."], ["Did you finish repairing the door?", "Você terminou de consertar a porta?"], ["Not yet. I keep losing the right tools.", "Ainda não. Eu continuo perdendo as ferramentas certas."], ["Would you mind holding the ladder for me?", "Você se importaria de segurar a escada para mim?"], ["Not at all. I do not mind helping.", "De jeito nenhum. Não me importo de ajudar."], ["Does your brother keep working in the evening?", "Seu irmão continua trabalhando à noite?"], ["Yes, he never stops until it is dark.", "Sim, ele só para quando escurece."]], ["O som /ŋ/ no final de -ing", "Em painting, o ing termina no nariz: a língua fica atrás e o g não é pronunciado.", ["painting", "I enjoy painting."]], ["Ben enjoys ___ the fence.", "painting", "to paint", "Ben gosta de pintar a cerca.", "Depois de enjoy, o verbo vai no -ing."]];
patterns[71]=new RegExp("\\b(enjoy|enjoys|finish|finishes|mind|keep|keeps|stops?) \\w+ing\\b|\\b(enjoy|enjoys|finish|finishes|keep|keeps|mind) \\w*ing\\b","i");
themes[71]="notebook";
