plans[72]={"title": "Hobbies no quintal", "file": "photo-parkPath-1.webp", "grammar": "Like, love, hate, prefer com -ing e com to", "goal": "Use like, love, hate e prefer com -ing ou com to + verbo para falar de gostos.", "words": [["grow", "cultivar"], ["plant", "plantar"], ["lawn", "gramado"], ["seed", "semente"]]};
content[72]=[[["Ava loves to work in the garden on warm days.", "Ava adora trabalhar no jardim em dias quentes."], ["She likes to grow tomatoes and plant flowers.", "Ela gosta de cultivar tomates e plantar flores."], ["She hates to see dry leaves on the plants.", "Ela detesta ver folhas secas nas plantas."], ["Her husband prefers reading in the shade to digging.", "O marido dela prefere ler na sombra a cavar."], ["Still, they both like to eat the fresh tomatoes.", "Mesmo assim, os dois gostam de comer os tomates frescos."]], [["Do you like to work in a garden?", "Você gosta de trabalhar num jardim?"], ["Yes, I love to plant flowers in spring.", "Sim, adoro plantar flores na primavera."], ["What do you enjoy on weekends?", "O que você faz nos fins de semana?"], ["I prefer swimming to staying at home.", "Prefiro nadar a ficar em casa."], ["Do you hate cooking when you are tired?", "Você odeia cozinhar quando está cansado?"], ["I do. I prefer to order a pizza.", "Odeio. Prefiro pedir uma pizza."], ["Does your sister like to walk in the park?", "Sua irmã gosta de caminhar no parque?"], ["Yes, she loves walking there with her dog.", "Sim, ela adora caminhar lá com o cachorro."]], ["Acento em garden e plant", "Em garden, o r vem forte depois da vogal: /ˈgɑrdn/.", ["plant", "I love to plant seeds."]], ["I prefer ___ at home to going out.", "staying", "stay", "Eu prefiro ficar em casa a sair.", "Depois de prefer, use -ing ou to + verbo, nunca o verbo sozinho."]];
patterns[72]=new RegExp("\\b(like|likes|love|loves|hate|hates|prefer|prefers) (to )?\\w+(ing)?\\b","i");
