plans[73]={"title": "Se chover, vamos ficar", "file": "photo-dusk-1.webp", "grammar": "If + presente, will: primeira condicional", "goal": "Use if + presente simples e will + verbo para falar de uma possibilidade real no futuro.", "words": [["cancel", "cancelar"], ["raincoat", "capa de chuva"], ["soaked", "encharcado"], ["sunshine", "sol"]]};
content[73]=[[["If there is a storm, Peg will cancel the picnic.", "Se houver tempestade, Peg vai cancelar o piquenique."], ["If it rains, we will stay at home.", "Se chover, vamos ficar em casa."], ["Tina says, \"If you wear a raincoat, you will not get wet.\"", "Tina diz: \"Se você vestir uma capa de chuva, não vai se molhar.\""], ["If Ravi forgets it, he will be soaked.", "Se Ravi esquecer, vai ficar encharcado."], ["If the weather is good, they will meet at noon.", "Se o tempo estiver bom, eles vão se encontrar ao meio-dia."]], [["What will you do if it rains tomorrow?", "O que você vai fazer se chover amanhã?"], ["If it rains, I will watch a movie at home.", "Se chover, vou ver um filme em casa."], ["Will you bring an umbrella if the sky is dark?", "Você vai levar guarda-chuva se o céu estiver escuro?"], ["Yes, I will take two, one for you.", "Vou, vou levar dois, um para você."], ["If the rain gets worse, will they cancel the game?", "Se a chuva piorar, eles vão cancelar o jogo?"], ["I think so. They will tell us by text.", "Acho que sim. Eles vão avisar por mensagem."], ["If you call me, I will answer right away.", "Se você me ligar, eu atendo na hora."], ["Good. I will call you at nine.", "Ótimo. Ligo para você às nove."]], ["A contração I will e o 'll", "Na fala, I will vira I'll, curtinho: /aɪl/. Em will, o w pede os lábios arredondados.", ["will", "If it rains, I will stay."]], ["If it rains, we ___ at home.", "will stay", "stay", "Se chover, vamos ficar em casa.", "Na primeira condicional, o resultado usa will + verbo."]];
patterns[73]=new RegExp("\\bif .*\\bwill\\b|\\bwill .*\\bif\\b","i");
themes[73]="city";
photos[73]=["photo-dusk-1.webp", "photo-street-1.webp"];
plans[74]={"title": "Acampar, a menos que chova", "file": "photo-lake-2.webp", "grammar": "Unless e when em frases condicionais simples", "goal": "Use unless para dizer a menos que e when para dizer quando em planos simples.", "words": [["camp", "acampar"], ["fishing", "pescaria"], ["hook", "anzol"], ["bait", "isca"]]};
content[74]=[[["Lia and Ben will camp by the river unless it rains.", "Lia e Ben vão acampar perto do rio a menos que chova."], ["They will go fishing when the sun comes up.", "Eles vão pescar quando o sol nascer."], ["Unless Ben brings a tent, they will sleep in the car.", "A menos que Ben traga uma barraca, eles vão dormir no carro."], ["When the food is ready, Lia calls her cousin.", "Quando a comida fica pronta, Lia chama o primo."], ["They will stay until Sunday unless it gets cold.", "Eles vão ficar até domingo a menos que esfrie."]], [["Are we going to camp on Saturday?", "Vamos acampar no sábado?"], ["Yes, unless the weather changes.", "Sim, a menos que o tempo mude."], ["What will you do when you get there?", "O que você vai fazer quando chegar lá?"], ["I will set up the tent when we arrive.", "Vou montar a barraca quando chegarmos."], ["Will you call me when you are ready for fishing?", "Você me liga quando estiver pronto para pescar?"], ["I will, unless my phone has no battery.", "Ligo, a menos que meu celular fique sem bateria."], ["Will they join us unless they have work?", "Eles vão se juntar a nós a menos que tenham trabalho?"], ["Yes, they will come when they finish at two.", "Sim, vão vir quando terminarem às duas."]], ["O som /ʌ/ em unless e Sunday", "Em unless e Sunday, a vogal é curta e relaxada, entre o a e o e do português: /ʌ/.", ["unless", "Unless it rains, we go."]], ["We will go ___ it rains.", "unless", "if not", "Vamos a menos que chova.", "Unless significa a menos que: ele já carrega a ideia de negação."]];
patterns[74]=new RegExp("\\b(unless|when) \\w+","i");
themes[74]="park";
