content[75]=[[["If you heat ice, it melts.", "Se você esquenta gelo, ele derrete."], ["When water gets very hot, it starts to boil.", "Quando a água fica muito quente, ela ferve."], ["If you put water in the freezer, it begins to freeze.", "Se você põe água no freezer, ela congela."], ["If Noah adds sugar to his tea, it tastes sweet.", "Se Noah põe açúcar no chá, ele fica doce."], ["Noah always uses cold water if he makes lemon juice.", "Noah sempre usa água fria se faz suco de limão."]], [["What happens if you leave ice in the sun?", "O que acontece se você deixa gelo no sol?"], ["It melts, and you get water.", "Ele derrete e você fica com água."], ["What happens when water gets to one hundred degrees?", "O que acontece quando a água chega a cem graus?"], ["It boils. You can see the bubbles.", "Ela ferve. Dá para ver as bolhas."], ["If I forget my milk outside, does it go bad?", "Se eu esqueço o leite fora, ele estraga?"], ["Yes, if it stays warm, it goes bad fast.", "Sim, se fica quente, estraga rápido."], ["Does ice float if you put it in a glass?", "O gelo flutua se você põe num copo?"], ["Yes, it always floats on the water.", "Sim, ele sempre flutua na água."]], ["O som /z/ final em melts e boils", "Em boils, termine com um /z/ vibrado. Em melts, o /ts/ final é seco e rápido.", ["boils", "Water boils at one hundred degrees."]], ["If you heat ice, it ___.", "melts", "will melts", "Se você esquenta gelo, ele derrete.", "No zero conditional, os dois verbos ficam no presente simples."]];
patterns[75]=new RegExp("\\b(if|when) [^,.?]*,? .*","i");
themes[75]="cup";
photos[75]=["photo-water-1.webp", "photo-coffeeTable-1.webp"];
