content[76]=[[["Ravi makes a budget so that he can travel in July.", "Ravi faz um orçamento para poder viajar em julho."], ["He uses a coupon to save money at the market.", "Ele usa um cupom para economizar dinheiro no mercado."], ["He cooks at home to spend less on food.", "Ele cozinha em casa para gastar menos com comida."], ["He walks to work so that he does not pay for the bus.", "Ele vai a pé ao trabalho para não pagar o ônibus."], ["In June, he buys a cheap ticket to Chicago.", "Em junho, ele compra uma passagem barata para Chicago."]], [["Why do you keep a budget?", "Por que você mantém um orçamento?"], ["I keep one so that I can save money.", "Mantenho um para poder economizar dinheiro."], ["Why did you take that coupon?", "Por que você pegou esse cupom?"], ["I took it to get a cheap lunch.", "Peguei para conseguir um almoço barato."], ["Why does Ben work on Saturdays?", "Por que o Ben trabalha aos sábados?"], ["He works so that he can buy a new bike.", "Ele trabalha para poder comprar uma bicicleta nova."], ["Why are you saving money?", "Por que você está economizando dinheiro?"], ["To visit my grandmother in Texas next summer.", "Para visitar minha avó no Texas no próximo verão."]], ["Entonação em Why...? e To...", "Em perguntas com why, a voz desce no fim. Na resposta, to é curto e fraco: /tə/.", ["save", "I save to travel."]], ["He walks to work ___ he can save money.", "so that", "for that", "Ele vai a pé ao trabalho para poder economizar dinheiro.", "So that liga o objetivo a uma frase completa."]];
patterns[76]=new RegExp("\\bso that\\b|\\b(to|in order to) (save|get|visit|buy|spend)\\b","i");
