plans[77]={"title": "Onde fica a plataforma?", "file": "photo-stationSign-1.webp", "grammar": "Perguntas indiretas simples: Do you know where…?", "goal": "Use Do you know where, what time ou how much para fazer uma pergunta educada, sem inverter o verbo.", "words": [["conductor", "cobrador"], ["delayed", "atrasado"], ["timetable", "tabela de horários"], ["announcement", "aviso"]]};
content[77]=[[["Lou is at the station and cannot find her train.", "Lou está na estação e não acha o trem dela."], ["She asks a woman, \"Do you know where the platform is?\"", "Ela pergunta a uma mulher: \"Você sabe onde fica a plataforma?\""], ["The woman does not know when the train leaves.", "A mulher não sabe a que horas o trem sai."], ["Lou checks the timetable and sees the train is delayed.", "Lou olha o horário e vê que o trem está atrasado."], ["She asks the conductor how long she must wait.", "Ela pergunta ao cobrador se ele sabe quanto tempo esperar."]], [["Excuse me, do you know where platform four is?", "Com licença, você sabe onde fica a plataforma quatro?"], ["Yes, it is down the stairs on the left.", "Sim, fica descendo a escada, à esquerda."], ["Can you tell me what time the train leaves?", "Pode me dizer a que horas o trem sai?"], ["I am not sure. Let us check the schedule.", "Não tenho certeza. Vamos ver o horário."], ["Do you know if the train is delayed?", "Você sabe se o trem está atrasado?"], ["Yes, it is twenty minutes late today.", "Sim, está vinte minutos atrasado hoje."], ["Could you tell me how much the ticket costs?", "Poderia me dizer quanto custa a passagem?"], ["It costs eleven dollars, I think.", "Custa onze dólares, eu acho."]], ["Ritmo de Do you know...?", "Una do you know em um bloco só: /dʒuˈnoʊ/. A voz sobe no final da pergunta.", ["platform", "Where is the platform?"]], ["Do you know where the platform ___?", "is", "is it", "Você sabe onde fica a plataforma?", "Em pergunta indireta, o verbo vem depois do sujeito, como numa afirmação."]];
patterns[77]=new RegExp("\\b(do you know|can you tell me|could you tell me) (where|what|how|if)\\b|\\b(knows?|know) (what|how|if|where)\\b","i");
themes[77]="map";
