plans[78]={"title": "O que você acha do filme?", "file": "photo-message-1.webp", "grammar": "Pedir e dar opiniões: I think, I do not think, in my opinion", "goal": "Use I think, I do not think e in my opinion para dar e pedir opiniões com educação.", "words": [["review", "crítica"], ["ending", "final"], ["opinion", "opinião"], ["plot", "enredo"]]};
content[78]=[[["Tina reads a review of the new movie.", "Tina lê uma crítica do filme novo."], ["In my opinion, the ending is the best part.", "Na minha opinião, o final é a melhor parte."], ["Her friend Nico thinks the story is boring.", "O amigo Nico acha a história chata."], ["I do not think so, says Tina with a smile.", "Não acho, diz Tina com um sorriso."], ["They agree that the music is great.", "Eles concordam que a música é ótima."]], [["What do you think of the movie?", "O que você acha do filme?"], ["I think it is great, but a little long.", "Acho ótimo, mas um pouco longo."], ["Do you think the ending is good?", "Você acha o final bom?"], ["No, I do not think it is very clear.", "Não, acho que não é muito claro."], ["What is your opinion of the actor?", "Qual é a sua opinião sobre o ator?"], ["In my opinion, he is the best one in the film.", "Na minha opinião, ele é o melhor do filme."], ["Do you think I should read the review?", "Você acha que eu devo ler a crítica?"], ["Yes, I think it will help you decide.", "Sim, acho que vai ajudar você a decidir."]], ["Entonação em I think...", "Em I think, a voz sobe um pouco em think e desce no fim da frase. O th é /θ/, com a língua entre os dentes.", ["opinion", "In my opinion, it is good."]], ["I ___ the ending is good.", "think", "am think", "Eu acho que o final é bom.", "Em inglês, diga I think, sem o verbo to be."]];
patterns[78]=new RegExp("\\b(I think|I do not think|in my opinion|do you think)\\b|\\bthinks\\b","i");
themes[78]="chat";
photos[78]=["photo-friends-1.webp", "photo-message-1.webp"];
plans[79]={"title": "A viagem do Ravi", "file": "photo-railpass-1.webp", "grammar": "Revisão do bloco: planos, condições e experiências", "goal": "Reveja verbos com infinitivo e -ing, condicionais, so that e perguntas indiretas numa história.", "words": [["terminal", "terminal"], ["boarding", "embarque"], ["customs", "alfândega"], ["pilot", "piloto"]]};
content[79]=[[["Ravi plans to fly to Boston on Friday morning.", "Ravi planeja voar para Boston na sexta de manhã."], ["If he forgets his passport, he will miss the flight.", "Se esquecer o passaporte, ele vai perder o voo."], ["He keeps checking his bag so that nothing is missing.", "Ele continua conferindo a mala para não faltar nada."], ["At the terminal, he asks, \"Do you know where my gate is?\"", "No terminal, ele pergunta: \"Você sabe onde fica meu portão?\""], ["In his opinion, boarding the plane is the best part.", "Na opinião dele, o embarque é a melhor parte."]], [["Do you want to come to the airport with me?", "Você quer ir ao aeroporto comigo?"], ["Yes, I will help with your luggage.", "Sim, vou ajudar com a sua bagagem."], ["Did you pack your passport?", "Você guardou o passaporte?"], ["Yes, I put it in my coat so that I will not lose it.", "Sim, pus no casaco para não perder."], ["Do you know what time we need to leave?", "Você sabe a que horas precisamos sair?"], ["If the traffic is bad, we will leave at six.", "Se o trânsito estiver ruim, saímos às seis."], ["What do you think about the new gate?", "O que você acha do novo portão?"], ["I think it is easy to find. I enjoy walking there.", "Acho fácil de achar. Gosto de caminhar até lá."]], ["Acento em airport e passport", "Nas duas palavras a força cai na primeira sílaba: /ˈɛrpɔrt/ e /ˈpæspɔrt/.", ["passport", "Show your passport, please."]], ["If he forgets it, he ___ the flight.", "will miss", "misses will", "Se ele esquecer, vai perder o voo.", "Primeira condicional: if + presente e will + verbo."]];
patterns[79]=new RegExp("\\b(if|so that|do you know|I think|I enjoy|plans to|want to)\\b","i");
themes[79]="ticket";
photos[79]=["photo-railpass-1.webp", "photo-luggage-1.webp"];
stories[79]=["A viagem do Ravi", "Ravi plans to visit his aunt in Boston.~Ravi planeja visitar a tia em Boston.|He wants to leave early so that he can relax.~Ele quer sair cedo para poder relaxar.|If he forgets his passport, he will miss the flight.~Se esquecer o passaporte, ele perde o voo.|At home, he keeps checking his bag again and again.~Em casa, ele continua conferindo a mala várias vezes.|At the airport, he asks where the right gate is.~No terminal, ele pergunta onde fica o portão certo.|A woman who works there shows him the way.~Uma mulher que trabalha lá mostra o caminho a ele.|He enjoys sitting near the window and watching planes.~Ele gosta de sentar perto da janela e ver aviões.|When the plane lands, he calls his aunt.~Quando o avião pousa, ele liga para a tia.|She waits at the station where they always meet.~Ela espera na estação onde eles sempre se encontram.|Ravi thinks the trip is the best surprise of June.~Ravi acha que a viagem é a melhor surpresa de junho."];
